-- Onboarding's goal libraries (the first session and Home's suggestion chips)
-- as built-in collections, so their affirmations can change without an app
-- release. Until now they were compiled into the app.
--
-- collections.goal names the onboarding goal a built-in collection belongs to
-- ("build_confidence", ...). Those collections stay off Explore and "For right
-- now": affirmations_get_library returns them under `goals` instead of
-- `builtin`. The app keeps its compiled copy as a fallback for a first launch
-- before the library has loaded.
--
-- 9 goals x 50 affirmations in 15 languages, taken from the app's string
-- catalog. Same id scheme as the other built-in seeds (collection, language,
-- position): a re-run inserts nothing and never overwrites. Each language's
-- items sit at language index * 100 + 1..50 in collection_items.

alter table affirmations.collections add column if not exists goal text;
create unique index if not exists collections_goal_key
  on affirmations.collections (goal) where goal is not null;

create temp table goal_seed (goal text, position int, icon text, tint text);

insert into goal_seed values
  ('build_confidence', 101, 'bolt.heart', 'amber'),
  ('reduce_anxiety', 102, 'wind', 'sky'),
  ('find_inner_peace', 103, 'leaf', 'mint'),
  ('find_motivation', 104, 'flame', 'coral'),
  ('cultivate_self_love', 105, 'heart.fill', 'rose'),
  ('heal_from_past_wounds', 106, 'heart.circle', 'violet'),
  ('improve_my_health', 107, 'figure.run', 'lime'),
  ('embrace_growth', 108, 'arrow.up.forward', 'teal'),
  ('strengthen_my_relationships', 109, 'person.2', 'peach');

insert into affirmations.collections (id, owner_id, kind, icon, tint, slug, position, moments, goal)
select md5('affirmations:collection:goal-' || goal)::uuid, null, 'builtin', icon, tint,
       'goal-' || goal, position, '{}', goal
from goal_seed
on conflict (id) do nothing;

drop table goal_seed;

create temp table goal_l10n (goal text, language text, base_position int, title text, texts text[]);

