  ('build_confidence', 'zh-hans', 1300, '建立自信', array[
    '此刻的我，就已经足够了。',
    '我的自信每一天都在不断增强。',
    '我属于这里，我值得占据自己的一席之地。',
    '没有什么能动摇我对自己的信念。',
    '我相信自己能做出正确的决定。',
    '我的声音是有意义的，值得被倾听。',
    '我散发着自信、力量与笃定。',
    '怀疑对我毫无影响。',
    '我为正在成为的那个人感到骄傲。',
    '我的存在真正带来了改变。',
    '我以勇气与平静迎接每一个挑战。',
    '每一次挫折都让我更坚强、更智慧。',
