    '我放下与他人的比较，拥抱属于自己的路。',
    '我内在的力量每一天都让我自己惊叹。',
    '我知道，我的存在是有意义的。',
    '做自己，已经绰绰有余。',
    '我吸引尊重，因为我首先尊重自己。',
    '我的潜力没有上限。',
    '我为自己已经走过的路感到骄傲。',
    '每一天，我都以最好的自己出现。',
    '我以开放的心态和平稳的心境面对这个世界。',
    '我的自信不是傲慢，而是自我尊重。',
    '即使没有人支持我，我也会支持自己。',
    '信任自己对我来说是自然而然的事。',
    '我已经足够了，一直都是。',
    '我自信、有能力，也完全是我自己。'
  ]),
