    '不安な思考を可能性の思考に置き換えます。',
    '息を吐くたびに体がどんどん深くくつろいでいきます。',
    '不確かな時代でも、私は支えられています。',
    '不確実性を恐れではなく好奇心をもって受け止めます。',
    '穏やかさはいつでも手の届くところにあります――私はただそれを選ぶだけです。',
    '私はどんな不安な考えよりも強いです。',
    '私の平和は周りで起きることに左右されません。',
    'スローダウンして、ただあることを自分に許します。',
    '流れに身を任せることが毎日より自然にできるようになっています。',
    '今すべての答えを持とうとする衝動を手放します。',
    '私の心は安全で優しい場所です。',
    '私は危険にさらされていません――安全で健やかです。',
    '静寂は私を回復させてくれ、私はよくそこに戻ります。',
    '立ち止まり、息をして、自分は大丈夫だと思い出します。',
    '手放すことが毎日より簡単で軽く感じられます。',
    '心の隅々まで平和を迎え入れます。',
    '自分への思考がどんどん優しく穏やかになっています。',
    'まさに今この瞬間、恐れよりも信頼を選びます。',
    '今この瞬間はいつでも対処できます。',
    '体に抱えてきた緊張を手放します。',
    '不安は溶けていき、穏やかさがその場所を取っています。',
    '自分の感情を感じ、それが過ぎていくのを安心して見守れます。',
    '息を吐くたびにストレスがどんどん遠ざかります。',
    '私は自分が思っている以上にたくましい存在です。',
    '心拍が落ち着き、体がくつろぎを取り戻します。',
    '何が来ても対処できる自分の力を信じています。',
    '変えられないことと穏やかに向き合います。',
    '深く息をするだけで、いつでも戻ってこられます。',
    '私は穏やかで、地に足がついていて、完全に大丈夫です。'
  ]),
