  ('reduce_anxiety', 'zh-hans', 1300, '减轻焦虑', array[
    '我是安全的，一切都在朝好的方向发展。',
    '我的呼吸是我的锚，我始终回归于它。',
    '我放下忧虑，在此刻选择平静。',
    '此刻是安全的，我一切都好。',
    '我相信一切都在按它应有的方式展开。',
    '我的神经系统平静而自在。',
    '我放下那些我无法掌控的。',
    '每一次呼吸，平静都在我体内流动。',
    '焦虑无法定义我，我比我的恐惧更强大。',
    '我的思绪清晰、平静而专注。',
    '在任何情况下，我都选择平静而非混乱。',
    '为明天担忧只会偷走今天的安宁。',
    '我吸入平静，呼出紧张。',
    '我的身体懂得如何寻得平衡与休息。',
    '我放下对一切结果的掌控欲。',
    '就在此刻，我完全没问题。',
    '我不是我的念头，我看着它们像云一样飘过。',
    '今天需要我处理的一切，我都能应对。',
    '我的内心越来越安静，越来越平和。',
    '我允许自己休息，不带任何愧疚。',
    '恐惧只是一种感觉，它伤不了我。',
    '我用充满可能性的念头取代焦虑的想法。',
    '每一次呼气，我的身体都在更深地放松。',
    '即使在不确定的时候，我也有所依托、有人支持。',
    '我以好奇而非恐惧来面对未知。',
    '平静随时都在，我只需选择它。',
    '我比任何焦虑的念头都要强大。',
    '我的平静不取决于外界发生了什么。',
    '我慢下来，让自己安然存在。',
    '信任这个过程，每天都变得更自然。',
    '我放下必须立刻找到所有答案的冲动。',
    '我的内心是一个安全而温柔的地方。',
    '我没有危险，我是安全的，我很好。',
    '静默让我恢复，我常常回到那里。',
    '我停下来，深呼吸，提醒自己一切都好。',
    '每一天，放手都变得更轻松、更自在。',
    '我欢迎平静进入内心的每一个角落。',
    '我对待自己的念头，正变得越来越温柔、越来越慈悲。',
    '在这一刻，我选择信任而非恐惧。',
    '当下时刻总是可以应对的。',
    '我释放一直紧绷在身体里的压力。',
    '我的焦虑正在消融，平静正在取而代之。',
    '我可以安全地感受自己的情绪，并让它们流走。',
    '每一次呼气，都将压力带得更远。',
    '我比自己意识到的更有韧性。',
    '我的心跳慢下来，身体找到了它的从容。',
    '我相信自己有能力应对任何降临的事。',
    '我与那些无法改变的事和平共处。',
    '深呼吸总是足以让我回到当下。',
    '我平静、我扎根，完全没问题。'
  ]),
  ('reduce_anxiety', 'zh-hant', 1400, '減輕焦慮', array[
