    '就在此刻，我選擇信任而非恐懼。',
    '當下的這一刻，永遠是可以應對的。',
    '我釋放一直積存在身體裡的緊張。',
    '我的焦慮正在消解，平靜正在取而代之。',
    '我可以安全地感受自己的情緒，讓它們流過。',
