  ('find_inner_peace', 'de', 100, 'Inneren Frieden finden', array[
    'Ich bin im Frieden mit meiner Vergangenheit, meiner Gegenwart und meiner Zukunft.',
    'Stille lebt in mir — ich kehre immer zu ihr zurück.',
    'Ich lasse den Drang los zu hetzen und vertraue dem Timing des Lebens.',
    'Friede ist nichts, das ich finde — er ist etwas, das ich wähle.',
    'Mein Herz ist ruhig, offen und entspannt.',
    'Ich bewege mich mit Leichtigkeit und Gelassenheit durch meinen Tag.',
    'Stille ist ein Geschenk, das ich mir jeden Tag mache.',
    'Ich lasse Widerstand los und fließe mit dem Rhythmus des Lebens.',
    'In den einfachsten Momenten wohnen Schönheit und Bedeutung.',
    'Ich vergebe mir für alles, was ich hätte anders machen können.',
    'Ich bin nicht im Wettlauf — ich bewege mich in meinem eigenen heiligen Tempo.',
    'Mein Geist ist ein friedlicher Ort, in dem ich mich immer willkommen fühle.',
    'Ich finde Frieden darin, das anzunehmen, was ich nicht ändern kann.',
    'Ich lasse das Gestern los und umarme diesen Moment vollständig.',
    'Ich atme Frieden ein und atme alles Schwere aus.',
    'Meine innere Welt ist ruhig, egal was mich umgibt.',
    'Ich lasse das Leben einfach sein und finde Freude in dieser Einfachheit.',
    'Ich lasse das Bedürfnis los, jetzt sofort alle Antworten zu haben.',
    'Ich wohne in der Ruhe, egal was gerade um mich herum passiert.',
    'Ich akzeptiere mich selbst ohne Bedingungen oder Vorbehalte.',
    'Loszulassen fühlt sich wie das Natürlichste der Welt an.',
    'Ich wähle Zufriedenheit in diesem gegenwärtigen Moment.',
    'Meine innere Welt ist ein Heiligtum, zu dem ich mühelos zurückfinde.',
    'Ich lebe mit offenem Herzen und friedvollem Geist.',
    'Ich finde mich ins Leben ein, anstatt dagegen anzukämpfen.',
    'Frieden ist mein Anker in jedem Sturm.',
    'Ich bin in jeder Lebensphase sanft zu mir selbst.',
    'Grübeln verlässt mich — Vertrauen nimmt seinen Platz ein.',
    'Ich akzeptiere das gesamte Spektrum meiner menschlichen Erfahrung.',
    'Ich finde Frieden in der Wahrheit, dass ich immer mein Bestes tue.',
    'Ich lasse jede Last los, die nicht mir gehört zu tragen.',
    'Ich bin bei mir selbst zuhause.',
    'Mein innerer Friede wird durch Lärm von außen nicht erschüttert.',
