    'Freude und Frieden coexistieren wunderschön in mir.',
    'Ich lasse alte Geschichten los, die nicht mehr widerspiegeln, wer ich bin.',
    'Mein Atem bringt mich jedes Mal wieder zu mir zurück.',
    'Ich bin frei vom Lärm der Welt.',
    'Ich vertraue darauf, dass alles genau so ist, wie es sein muss.',
    'Ich bin still, ich bin präsent und ich bin ganz.',
    'Mein Nervensystem ist sicher, ruhig und entspannt.',
    'Ich wähle Frieden über das Rechthaben — jedes Mal.',
    'Ich ruhe in dem Wissen, dass ich genau dort bin, wo ich sein muss.',
    'Jeden Tag bringt mehr Frieden und mehr Leichtigkeit in mein Leben.',
    'Ich trage Stille mit mir, wohin ich auch gehe.',
    'Ich bin friedvoll, ich bin präsent und ich bin frei.'
  ]),
  ('find_inner_peace', 'fr', 200, 'Trouver la paix intérieure', array[
    'Je suis en paix avec mon passé, mon présent et mon futur.',
    'Le silence vit en moi — j''y reviens toujours.',
    'Je renonce au besoin de me presser et je fais confiance au rythme de la vie.',
    'La paix n''est pas quelque chose que je trouve — c''est quelque chose que je choisis.',
    'Mon cœur est tranquille, ouvert et apaisé.',
    'J''avance dans ma journée avec légèreté et sérénité.',
    'Le silence est un cadeau que je m''offre chaque jour.',
    'Je lâche toute résistance et je me laisse porter par le rythme de la vie.',
    'La beauté et le sens se trouvent dans les moments les plus simples.',
    'Je me pardonne tout ce que j''aurais pu faire différemment.',
    'Je ne suis pas dans une course — j''avance à mon propre rythme sacré.',
    'Mon esprit est un endroit paisible où je me sens toujours le(la) bienvenu(e).',
    'Je trouve la paix en acceptant ce que je ne peux pas changer.',
    'Je laisse partir hier et j''embrasse pleinement ce moment.',
    'J''inspire la paix et j''expire tout ce qui est lourd.',
    'Mon monde intérieur est calme, quelle que soit l''agitation qui m''entoure.',
    'Je m''autorise à vivre simplement et à trouver la joie dans cette simplicité.',
