    'Bu ana yerleşiyor ve onun yeterli olduğunu görüyorum.',
    'Başkalarını affetmek beni özgür kılıyor — ve özgürlüğü seçiyorum.',
    'Sessizlikten besleniyorum ve hareketsizlikle yeniliyorum.',
    'Gitmeye ihtiyacı olanı, direnmeden gitmesine izin veriyorum.',
    'Belirsizliği açık ve güvenen bir yürekle kucaklıyorum.',
