  ('find_inner_peace', 'ar', 1000, 'اعثر على السلام الداخلي', array[
    'أنا في سلام مع ماضيّ وحاضري ومستقبلي.',
    'الصمت يسكن داخلي وأعود إليه دائمًا.',
    'أتحرر من الحاجة إلى التسرع وأثق في توقيت الحياة.',
    'السلام ليس شيئًا أجده، بل شيء أختاره.',
    'قلبي هادئ ومنفتح ومرتاح.',
    'أمر في يومي بيسر وسكينة.',
    'الصمت هدية أمنحها لنفسي كل يوم.',
    'أتحرر من المقاومة وأنساب مع إيقاع الحياة.',
    'الجمال والمعنى يسكنان أبسط اللحظات.',
    'أسامح نفسي على كل ما كان بإمكاني فعله بشكل مختلف.',
    'أنا لست في سباق، أتحرك بوتيرتي المقدسة الخاصة.',
    'عقلي مكان هادئ أشعر فيه بالترحيب دائمًا.',
    'أجد السلام في قبول ما لا أستطيع تغييره.',
    'أترك الأمس وأحتضن هذه اللحظة بالكامل.',
    'أستنشق السلام وأزفر كل ما هو ثقيل.',
    'عالمي الداخلي هادئ بغض النظر عما يحيط بي.',
    'أسمح للحياة أن تكون بسيطة وأجد البهجة في تلك البساطة.',
    'أتحرر من الحاجة إلى امتلاك كل الإجابات الآن.',
    'أسكن في الهدوء مهما كان يجري من حولي.',
    'أقبل نفسي بلا شروط أو قيود.',
    'الإفراج عن الأشياء يبدو أكثر الأمور طبيعية في العالم.',
    'أختار الرضا في هذه اللحظة الحاضرة.',
    'عالمي الداخلي ملاذ أعود إليه بيسر.',
    'أعيش بقلب منفتح وعقل مسالم.',
    'أنسجم مع الحياة بدلًا من الصراع معها.',
    'السلام مرساتي في كل عاصفة.',
    'أكون لطيفًا مع نفسي في كل فصل من فصول الحياة.',
    'الإفراط في التفكير يرحل عني والثقة تحل محله.',
    'أقبل الطيف الكامل من تجربتي الإنسانية.',
    'أجد السلام في الحقيقة أنني أبذل دائمًا قصارى جهدي.',
    'أتحرر من كل عبء ليس عليّ حمله.',
    'أشعر بالانتماء داخل نفسي.',
    'سلامي الداخلي لا يتزعزع بالضوضاء الخارجية.',
    'أستقر في هذه اللحظة وأجدها كافية.',
    'مسامحة الآخرين تحررني وأنا أختار الحرية.',
    'الصمت يغذّيني والهدوء يجدّدني.',
    'أدع ما يحتاج إلى المغادرة يرحل دون مقاومة.',
    'أحتضن عدم اليقين بقلب منفتح وموثوق.',
    'البهجة والسلام يتعايشان بجمال داخلي.',
    'أتحرر من القصص القديمة التي لم تعد تعكس هويتي.',
    'أنفاسي تعيدني إلى مركزي في كل مرة.',
    'أنا حر من ضجيج العالم.',
    'أثق بأن كل شيء هو بالضبط كما يجب أن يكون.',
    'أنا ساكن وحاضر ومكتمل.',
    'جهازي العصبي آمن ومستقر ومرتاح.',
    'أختار السلام على أن أكون محقًا في كل مرة.',
    'أستريح في اليقين بأنني في المكان الذي يجب أن أكون فيه.',
