  ('find_inner_peace', 'ja', 1100, '心の安らぎを見つける', array[
    '過去も、現在も、未来も、私は平和の中にあります。',
    '静寂は私の内側に生きています――私はいつでもそこに戻ります。',
    '急ぐ必要を手放し、人生のタイミングを信頼します。',
    '平和は見つけるものではなく、選ぶものです。',
    '私の心は静かで、開かれていて、くつろいでいます。',
    '私は穏やかさと安らぎをもって一日を過ごします。',
    '静寂は毎日自分に贈るギフトです。',
    '抵抗を手放し、人生のリズムに流れを任せます。',
    '最もシンプルな瞬間の中に美しさと意味が宿っています。',
    '違うやり方ができたすべてのことを、自分に許します。',
    '私はレースに参加していません――自分だけの神聖なペースで進みます。',
    '私の心はいつでも歓迎される平和な場所です。',
    '変えられないことを受け入れることに平和を見出します。',
    '昨日を手放し、この瞬間を丸ごと受け入れます。',
    '平和を吸い込み、重いものをすべて吐き出します。',
    '何が周りで起きていても、私の内側は穏やかです。',
    '人生をシンプルにすることを自分に許し、その中に喜びを見つけます。',
    '今すべての答えを必要としないことを手放します。',
    '何が起きていても、穏やかさの中に留まります。',
    '条件なく、ありのままの自分を受け入れます。',
    '手放すことは世界で一番自然なことのように感じます。',
    '今この瞬間に満足を選びます。',
    '私の内なる世界は、いつでも楽に戻れる聖域です。',
    '開かれた心と穏やかな心で生きます。',
    '人生と戦うのではなく、人生の中に柔らかく溶け込みます。',
    '平和はどんな嵐の中でも私のよりどころです。',
    '人生のどの季節にも、自分に優しく接します。',
    '考えすぎは去っていき、信頼がその場所を取っています。',
    '人間としての経験の全てを受け入れます。',
    'いつでも全力を尽くしているという真実の中に平和を見出します。',
    '自分のものではない荷物を手放します。',
    '私は自分の内側に家を持っています。',
    '外からのノイズに私の内なる平和は揺らぎません。',
    'この瞬間に落ち着き、これで十分だと気づきます。',
    '他者を許すことで自由になれます――そして私は自由を選びます。',
    '静寂に養われ、静けさによって回復します。',
    '去るべきものは抵抗なく去らせます。',
    '開かれた信頼の心で不確実性を受け入れます。',
    '喜びと平和は私の内側で美しく共存しています。',
    '自分をもはや表していない古い物語を手放します。',
    '息をするたびに、何度でも自分の中心に戻ってきます。',
    '世界のノイズから自由です。',
    'すべては必要なとおりであると信じています。',
    '私は静かで、今ここにいて、そして完全です。',
    '私の神経系は安全で、落ち着いていて、くつろいでいます。',
    '正しさよりも平和を選びます――いつでも。',
    '自分がちょうどいる場所にいることをわかって、そこに安らぎます。',
    '毎日、もっと平和で、もっと心地よい日々が訪れます。',
    'どこに行っても、静けさを持ち歩きます。',
    '私は穏やかで、今ここにいて、自由です。'
  ]),
  ('find_inner_peace', 'ko', 1200, '내면의 평화 찾기', array[
