    '나는 이 현재 순간에 만족을 선택합니다.',
    '나의 내면 세계는 내가 편안하게 돌아오는 성소입니다.',
    '나는 열린 마음과 평화로운 정신으로 살아갑니다.',
    '나는 삶과 맞서 싸우는 대신 부드럽게 그것에 몸을 맡깁니다.',
    '평화는 모든 폭풍 속의 나의 닻입니다.',
    '나는 삶의 모든 계절에서 나 자신에게 온화합니다.',
    '과도한 생각이 나를 떠나가고 — 신뢰가 그 자리를 차지하고 있습니다.',
