    '나는 옳고 그름보다 평화를 선택합니다 — 매번.',
    '나는 내가 있어야 할 곳에 정확히 있다는 앎 속에서 쉽니다.',
    '매일 내 삶에 더 많은 평화와 편안함이 찾아옵니다.',
    '나는 어디를 가든 고요함을 지니고 다닙니다.',
    '나는 평화롭고, 현재에 있으며, 자유롭습니다.'
