  ('find_inner_peace', 'zh-hans', 1300, '寻得内心的安宁', array[
    '我与我的过去、现在和未来和平共处。',
    '静默住在我内心，我总能回归于它。',
    '我放下急于求成的心，信任生命自有它的节奏。',
    '平静不是我寻找到的，而是我选择的。',
    '我的心安静、开放、自在。',
    '我以从容与宁静流过每一天。',
    '静默是我每天给自己的礼物。',
    '我放下抗拒，随生命的韵律流动。',
    '美丽与意义藏在最简单的时刻里。',
    '我原谅自己所有本可以做得不同的事。',
    '我不在赛跑中，我以自己神圣的步伐前行。',
    '我的内心是一个我总感到受欢迎的平静之地。',
    '我在接受无法改变的事中找到平静。',
    '我放下昨天，全然拥抱此刻。',
    '我吸入平静，呼出一切沉重。',
    '无论周围发生什么，我的内心世界都是平静的。',
    '我让生命简单，并在那简单中找到喜悦。',
    '我放下必须立刻拥有所有答案的执念。',
    '无论周围发生什么，我都居于平静之中。',
    '我无条件、无保留地接受自己。',
    '放手感觉是世界上最自然的事。',
    '我在此刻选择知足。',
    '我的内心世界是一个我轻松回归的圣地。',
    '我以开放的心和平静的头脑生活。',
    '我柔软地融入生命，而非与之对抗。',
    '平静是我在每一场风暴中的锚。',
    '在生命的每一个季节，我都对自己温柔。',
    '过度思考正在离我远去，信任正在取而代之。',
    '我接受完整的人类体验的全部光谱。',
    '我在知道自己始终尽力而为的真相中找到平静。',
    '我放下每一个不属于我承担的重担。',
    '我在自己内心安居。',
    '我的内心平静不被外界的喧嚣所动摇。',
    '我沉入这一刻，发现它已经足够。',
    '宽恕他人让我自由，而我选择自由。',
    '我被静默滋养，被宁静修复。',
    '我让需要离去的，离去，不带抵抗。',
    '我以开放而信任的心拥抱不确定性。',
    '喜悦与平静在我内心美妙地共存。',
    '我放下那些不再反映我是谁的旧故事。',
    '我的呼吸每一次都将我带回中心。',
    '我自由于世界的喧嚣之外。',
    '我相信一切都恰如其所需的那样。',
    '我静止、我临在、我完整。',
    '我的神经系统安全、平稳、自在。',
    '每一次，我都选择平静而非争论谁对谁错。',
    '我安住于知道自己恰好在应在之处的感知中。',
    '每一天都为我的生命带来更多平静与从容。',
    '无论去往何处，我都携带着宁静。',
    '我平静、我临在、我自由。'
  ]),
  ('find_inner_peace', 'zh-hant', 1400, '尋得內心的平靜', array[
    '我與自己的過去、現在和未來都和平共處。',
    '靜定住在我內心，我時刻回歸它。',
    '我放下急於求成的需要，信任生命的時機。',
    '平靜不是我找到的東西，而是我選擇的東西。',
    '我的心是安靜的、開放的、自在的。',
    '我帶著輕鬆與寧靜走過每一天。',
    '靜默是我每天給予自己的禮物。',
    '我放下抗拒，隨著生命的節奏流動。',
    '美麗與意義存在於最簡單的時刻之中。',
    '我原諒自己所有本可以做得不同的事。',
    '我不在賽跑中，我以自己神聖的節奏前行。',
    '我的心靈是一個讓我永遠感到受歡迎的平靜之地。',
    '我在接受那些無法改變的事情中找到平靜。',
    '我放下昨天，完整地擁抱此刻。',
    '我吸入平靜，呼出所有沉重。',
    '無論外在環境如何，我的內心世界都是平靜的。',
    '我讓生活簡單，並在這份簡單中找到喜悅。',
    '我放下此刻必須知道所有答案的需求。',
