  ('find_motivation', 'ru', 800, 'Больше мотивации', array[
    'Я просыпаюсь каждый день с целью, энергией и стремлением.',
    'Мой потенциал безграничен, и я только начинаю.',
    'Я делаю последовательные шаги к жизни, которую строю.',
    'Каждый шаг вперёд, каким бы маленьким он ни был, это прогресс.',
