    'أثق بأن عملي الجاد يؤتي ثماره دائمًا.',
    'الزخم يتراكم في حياتي وأشعر بذلك.',
    'أشعر بالنشاط من خلال الإمكانات وأنجذب للأمام بهدفي.',
    'الاستسلام ليس خيارًا بالنسبة لي.',
    'أنا ملتزم بالتميز في كل ما أفعله.',
