    'أحوّل العقبات إلى ديناميّات دون تردد.',
    'أستيقظ بنية وأنام بارتياح.',
    'تحفيزي يأتي من الداخل، لا شيء يستطيع أخذه.',
    'أفعل الأشياء الصعبة لأنني أعلم أنها تجعلني أقوى.',
    'كل جهد أبذله اليوم يتراكم في نتائج الغد.',
    'أُحرَّك بالهدف ومنجذب للأمام برؤيتي.',
