  ('find_motivation', 'ja', 1100, 'やる気を高める', array[
    '私は毎日目的と活力と情熱をもって目覚めます。',
    '私の可能性は限りなく、私はようやく始まったばかりです。',
    '私は自分が作り上げている人生に向けて、着実に行動し続けます。',
    'どれほど小さくても、一歩前進すればそれは進歩です。',
    '私の目標は私を奮い立たせ、毎日前へ引っ張ってくれます。',
    '毎日、迷いよりも行動を選びます。',
    '努力することは自然で、深く充実感をもたらします。',
    'やる気が低くても、自分のために姿を現します。',
    'すべての障害は、解決を待つチャレンジにすぎません。',
    '私のビジョンはどんな言い訳よりも大きいです。',
    '準備ができる前に始めます――自分が有能だとわかっているから。',
    '規律は未来の自分への贈り物です。',
    '言い訳を努力に、疑いを行動に置き換えます。',
    '私の継続性が何か素晴らしいものを作り上げています。',
    '完璧な瞬間を待つのではなく、自分で作り出します。',
    '仕事への姿勢は私の最大の強みのひとつです。',
    '先延ばしを乗り越え、今すぐ次の一歩を踏み出します。',
    '完璧さではなく進歩が私を前に進めます。',
    '私は意味のあるものを作り上げており、絶対にやめません。',
    '直面するすべての困難は前進するための燃料になります。',
    '私の野心は献身によってのみ匹敵します。',
    '起き上がり、立ち向かい、決して諦めません。',
    '難しいことも、取り組み続けるほど楽になっていきます。',
    '私は最も大切なことに集中しています。',
    '未来の自分は今日の私のしていることに感謝するでしょう。',
    '何に向かって取り組んでいるかを知っているから、続けられます。',
    '毎朝が前進する新たなチャンスです。',
    '大きな夢を小さなステップに分解し、一つずつ進みます。',
    '成長への渇望が毎日私をもっと遠くへ押し進めます。',
    'すべての節目を祝います――進歩は認めてもらう価値があるから。',
    '自分の努力は必ず報われていると信じています。',
    '私の人生には勢いが生まれています――それを感じられます。',
    '可能性にエネルギーをもらい、目的に引っ張られます。',
    'あきらめることは私には選択肢にありません。',
    'すべてのことに全力を尽くします。',
    '自分のビジョンへの信念は毎日強くなっています。',
    '障害を迷わず踏み台に変えます。',
    '意図をもって目覚め、満足とともに眠りにつきます。',
    '私のモチベーションは内側から来ています――何も奪えません。',
    '難しいことをするのは、それが自分を強くすると知っているからです。',
    '今日の一つひとつの努力が明日の結果となって積み重なります。',
    '目的に動かされ、ビジョンに引っ張られます。',
    '動き続けることが自然に、容易にできるようになっています。',
    '始めたことを最後までやり遂げる人間です。',
    '成長への欲求は快適さへの欲求より強いです。',
    '進みが遅くても、自分の目標を信じます。',
    '本当に大切なことに全力を注ぎます。',
    'エネルギーと集中力をもって、あらゆる挑戦に立ち向かいます。',
    '私の未来は今日の行動によって作られています。',
    '私はやる気があり、集中していて、準備ができています。'
  ]),
  ('find_motivation', 'ko', 1200, '동기 키우기', array[
    '나는 매일 목적, 에너지, 그리고 의욕을 갖고 일어납니다.',
    '나의 가능성은 무한하고 나는 이제 막 시작하고 있습니다.',
    '나는 내가 만들어가고 있는 삶을 향해 꾸준히 행동합니다.',
    '아무리 작은 한 걸음이라도 앞으로 나아가는 것은 전진입니다.',
    '나의 목표는 나를 흥분시키고 매일 앞으로 이끌어 줍니다.',
    '나는 매일 망설임보다 행동을 선택합니다.',
    '열심히 일하는 것은 내게 자연스럽고 깊이 보람 있는 일입니다.',
    '동기가 낮을 때도 나는 나 자신을 위해 나타납니다.',
    '모든 장애물은 해결되기를 기다리는 도전일 뿐입니다.',
    '나의 비전은 내가 만들 수 있는 어떤 변명보다도 큽니다.',
    '나는 준비되기 전에 시작합니다, 왜냐하면 내가 능력이 있다는 것을 알기 때문입니다.',
    '규율은 내가 미래의 나 자신에게 주는 선물입니다.',
    '나는 변명을 노력으로, 의심을 행동으로 대체합니다.',
    '나의 일관성은 특별한 무언가를 만들어 가고 있습니다.',
    '나는 완벽한 순간을 기다리지 않습니다 — 나는 그것을 만들어 냅니다.',
    '나의 직업 윤리는 나의 가장 큰 강점 중 하나입니다.',
    '나는 미루는 습관을 넘어서 지금 다음 단계를 밟습니다.',
    '완벽함이 아닌 전진이 나를 앞으로 이끄는 것입니다.',
    '나는 의미 있는 것을 만들고 있으며 절대 포기하지 않을 것입니다.',
    '내가 직면하는 모든 도전은 나를 앞으로 밀어주는 연료입니다.',
    '나의 야망은 오직 나의 헌신에 의해서만 맞먹습니다.',
    '나는 일어서고, 나타나고, 절대 포기하지 않습니다.',
    '어려운 것들은 내가 그것에 더 헌신할수록 더 쉬워집니다.',
    '나는 나에게 가장 중요한 것에 레이저처럼 집중합니다.',
    '미래의 나는 내가 오늘 하고 있는 것에 감사해할 것입니다.',
    '나는 내가 무엇을 향해 나아가고 있는지 정확히 알기 때문에 끈기 있게 계속합니다.',
    '매일 아침은 앞으로 나아갈 수 있는 새로운 기회입니다.',
    '나는 큰 꿈을 단계들로 나누고 하나씩 실행합니다.',
    '성장에 대한 나의 열망은 매일 나를 더 멀리 밀어줍니다.',
    '나는 모든 이정표를 축하합니다, 왜냐하면 전진은 인정받을 자격이 있기 때문입니다.',
    '나는 나의 노력이 언제나 결실을 맺고 있다고 신뢰합니다.',
    '나의 삶에 추진력이 쌓이고 있습니다 — 나는 그것을 느낄 수 있습니다.',
    '나는 가능성에 의해 에너지를 얻고 목적에 의해 앞으로 이끌립니다.',
    '포기하는 것은 단순히 나에게 선택지가 아닙니다.',
    '나는 내가 하는 모든 것에서 탁월함을 추구합니다.',
    '나의 비전에 대한 믿음은 매일 더욱 강해집니다.',
    '나는 망설임 없이 장애물을 발판으로 바꿉니다.',
    '나는 의도를 갖고 일어나고 만족감을 갖고 잠자리에 듭니다.',
    '나의 동기는 내면에서 옵니다 — 아무것도 그것을 빼앗아 갈 수 없습니다.',
    '나는 어려운 일들이 나를 더 강하게 만든다는 것을 알기 때문에 그것들을 합니다.',
    '오늘 내가 하는 모든 노력은 내일의 결과로 쌓입니다.',
    '나는 목적에 의해 움직이고 나의 비전에 의해 앞으로 이끌립니다.',
    '움직임을 유지하는 것은 내게 자연스럽고 쉬운 일입니다.',
    '나는 시작한 것을 끝내는 사람입니다.',
    '성장에 대한 나의 욕구는 안락함에 대한 욕망보다 더 강합니다.',
    '진전이 느릴 때도 나는 나의 목표를 믿습니다.',
    '나는 진정으로 중요한 모든 것에 최선의 노력을 다합니다.',
    '나는 에너지와 집중력으로 모든 도전을 맞이합니다.',
    '나의 미래는 오늘 내가 취하는 행동들에 의해 만들어지고 있습니다.',
    '나는 동기 부여되어 있고, 집중되어 있으며, 준비되어 있습니다.'
  ]),
  ('find_motivation', 'zh-hans', 1300, '增强动力', array[
    '我每天都带着目标、活力与动力醒来。',
    '我的潜力是无限的，而我才刚刚开始。',
    '我持续采取行动，朝着我正在构建的生活迈进。',
    '每一步向前，无论多小，都是进步。',
    '我的目标令我兴奋，每天都在拉着我向前。',
    '每一天，我都选择行动而非犹豫。',
    '努力对我来说感觉自然，且深深令人满足。',
    '即使动力低落，我也会为自己出现。',
    '每一个障碍都只是等待被解决的挑战。',
    '我的愿景比我能找到的任何借口都更宏大。',
    '我在准备好之前就开始，因为我知道自己有能力。',
    '自律是我给未来的自己的礼物。',
    '我用努力取代借口，用行动取代怀疑。',
    '我的坚持正在积累出非凡的成果。',
    '我不等待完美时机，我创造它。',
    '我的职业道德是我最大的优势之一。',
    '我超越拖延，立刻迈出下一步。',
    '推动我前进的是进步，而非完美。',
    '我正在构建有意义的事，我拒绝放弃。',
    '我面对的每一个挑战都是推动我前进的燃料。',
    '我的雄心只有我的付出能与之匹敌。',
    '我站起来，出现，永不放弃。',
    '越坚持，困难的事就越变得容易。',
    '我高度专注于对我最重要的事。',
    '我未来的自己感激我今天所做的一切。',
    '我坚持，因为我清楚地知道自己在为什么而努力。',
    '每一个早晨都是向前迈进的新机会。',
    '我把宏大的梦想拆解成步骤，一步一步走下去。',
    '我对成长的渴望每天都在推动我走得更远。',
    '我庆祝每一个里程碑，因为进步值得被认可。',
    '我相信我的努力始终都在产生回报。',
    '我的生命中正在积聚动力，我能感受到。',
    '我被可能性激励，被目标拉着向前。',
    '放弃对我来说根本不是一个选项。',
    '我致力于在每一件事上追求卓越。',
    '我对愿景的信念每天都在增强。',
    '我毫不犹豫地将障碍变成垫脚石。',
    '我带着意图醒来，带着满足感入睡。',
    '我的动力来自内心，没有什么能夺走它。',
    '我做困难的事，因为我知道它们让我更强大。',
    '我今天付出的每一分努力都在复利到明天的结果。',
    '我由目标驱动，被愿景拉着向前。',
    '保持前进的状态对我来说是自然而然的事。',
    '我是那种能做完自己开始的事的人。',
    '我渴望成长的力量比渴望舒适的欲望更强。',
    '即使进步缓慢，我也相信自己的目标。',
    '我把全力投入到每一件真正重要的事上。',
    '我以充沛的精力和专注迎接每一个挑战。',
    '我的未来正在由我今天的行动构建。',
    '我充满动力、我专注，我已准备好。'
  ]),
  ('find_motivation', 'zh-hant', 1400, '提升動力', array[
