    '我為正在建立的生活採取持續的行動。',
    '每一步向前，無論多小，都是進步。',
    '我的目標讓我興奮，每天都在拉著我前進。',
    '每一天我都選擇行動而非猶豫。',
    '努力工作對我而言感覺自然而深具意義。',
    '即使在動力低落時，我也為自己出現。',
    '每一個障礙只是等待被解決的挑戰。',
    '我的願景比任何我能找到的藉口都更宏大。',
    '我在準備好之前就開始，因為我知道自己有能力。',
    '自律是我給予未來自己的禮物。',
    '我用努力取代藉口，用行動取代懷疑。',
    '我的持續性正在建立一些非凡的事物。',
    '我不等待完美的時機，我創造它。',
    '我的職業道德是我最大的力量之一。',
    '我超越拖延，現在就採取下一步。',
    '驅動我前進的是進步，而非完美。',
    '我正在建立有意義的事物，我拒絕放棄。',
    '我面對的每一個挑戰都是推動我前進的燃料。',
    '我的雄心與我的奉獻精神相互媲美。',
    '我站起來、出現，永不放棄。',
    '我越是投入，困難的事情就越變得容易。',
    '我高度專注在對我最重要的事情上。',
    '我未來的自己為我今天所做的事而感恩。',
    '我堅持，因為我清楚地知道自己在朝哪個方向努力。',
    '每一個早晨都是向前邁進的新機會。',
    '我將大夢想分解成步驟，一步一步地去實現它們。',
    '我對成長的渴望每天都推動我走得更遠。',
    '我慶祝每一個里程碑，因為進步值得被認可。',
    '我相信我的努力永遠都在得到回報。',
    '我感覺到動力正在我的生命中積聚。',
    '我被可能性所激勵，被目標所牽引前進。',
    '放棄，根本不是我的選項。',
    '我致力於在所做的每件事上追求卓越。',
    '我對自己願景的信念每天都在增強。',
    '我毫不猶豫地將障礙化為墊腳石。',
    '我帶著意圖醒來，帶著滿足入睡。',
    '我的動力來自內心，沒有什麼能奪走它。',
    '我做困難的事，因為我知道它們讓我更強大。',
    '我今天的每一分努力都會累積成明天的成果。',
    '我由目標驅動，被願景牽引前行。',
    '保持行動對我而言是自然而輕鬆的事。',
    '我是那種做事能有始有終的人。',
    '我對成長的渴望比對安逸的渴望更強烈。',
    '即使進度緩慢，我也相信自己的目標。',
    '我全力以赴去做每一件真正重要的事。',
    '我精力充沛地迎接每一個挑戰，並全神貫注。',
    '我的未來正在被我今天的行動所建立。',
    '我是積極進取的、是專注的、我已準備好了。'
  ]),
  ('cultivate_self_love', 'en', 0, 'Cultivate self-love', array[
    'I am worthy of my own love and I give it freely.',
    'My relationship with myself is the most important one I have.',
    'I treat myself with the same kindness I give to those I love.',
    'I am enough, always, without needing to prove anything.',
    'My needs matter and I honor them without apology.',
    'I choose myself every single day without guilt.',
    'Being my own best friend comes naturally to me.',
    'I deserve good things and I allow myself to receive them.',
    'I am gentle, patient, and compassionate toward myself.',
    'My flaws are part of what makes me beautifully human.',
    'I release self-criticism and replace it with self-compassion.',
    'I am proud of who I am and the journey that shaped me.',
    'I give myself permission to rest, play, and simply enjoy life.',
    'Celebrating myself does not require an occasion.',
    'I am worthy of love, connection, and deep belonging.',
    'I forgive myself for my mistakes — they made me wiser.',
    'I let go of the belief that I need to earn my own love.',
    'My worth is inherent and nothing can take it away.',
    'I invest in myself because I know I am worth it.',
    'I talk to myself with kindness and refuse to be my own critic.',
    'My body deserves love and care at every stage of life.',
    'I see my own beauty clearly and without hesitation.',
    'I allow myself to receive compliments and love gracefully.',
    'I am not too much — I am exactly enough.',
    'My happiness matters just as much as anyone else''s.',
    'I release the habit of putting myself last.',
    'I am someone I am genuinely proud to spend time with.',
    'I love who I am becoming with every passing day.',
    'My worth is not tied to my productivity or achievements.',
    'I set boundaries because I love and respect myself deeply.',
    'I choose relationships that reflect the love I have for myself.',
    'I allow myself to be happy right now, without conditions.',
    'I appreciate my uniqueness and stop apologizing for it.',
    'I am the love I have been looking for all along.',
    'I give myself the grace I so easily extend to others.',
    'I hold myself with tenderness in the hard moments.',
    'My inner world is a place of warmth and acceptance.',
    'I deserve a life that feels as good on the inside as it looks.',
    'I no longer abandon myself to please others.',
    'Self-love is not selfish — it is essential.',
    'I honor my healing as sacred and deeply important.',
    'I choose to see myself through compassionate eyes.',
    'I am allowed to take up space, to bloom, and to be loved.',
    'My sensitivity is a strength, not a weakness.',
    'I am learning to love myself more fully every single day.',
    'I deserve the same love I so generously give to others.',
    'I am deeply and unconditionally worthy of my own love.',
    'Being kind to myself is a practice I commit to daily.',
    'I love every part of myself, including the parts still healing.',
    'I love myself — and that is more than enough to begin.'
  ]),
  ('cultivate_self_love', 'de', 100, 'Selbstliebe stärken', array[
    'Ich bin meiner eigenen Liebe würdig und schenke sie mir großzügig.',
    'Meine Beziehung zu mir selbst ist die wichtigste, die ich habe.',
    'Ich behandle mich mit derselben Freundlichkeit, die ich den Menschen schenke, die ich liebe.',
    'Ich bin genug, immer, ohne etwas beweisen zu müssen.',
    'Meine Bedürfnisse sind wichtig und ich beachte sie ohne zu entschuldigen.',
    'Ich wähle mich selbst jeden einzelnen Tag ohne schlechtes Gewissen.',
    'Mein eigener bester Freund zu sein fällt mir ganz natürlich.',
    'Ich verdiene Gutes und erlaube mir, es zu empfangen.',
    'Ich bin sanft, geduldig und mitfühlend mir selbst gegenüber.',
    'Meine Fehler sind Teil dessen, was mich zutiefst menschlich macht.',
    'Ich lasse Selbstkritik los und ersetze sie durch Selbstmitgefühl.',
    'Ich bin stolz darauf, wer ich bin und auf den Weg, der mich geformt hat.',
    'Ich erlaube mir, zu ruhen, zu spielen und das Leben zu genießen.',
    'Mich selbst zu feiern braucht keinen besonderen Anlass.',
    'Ich bin würdig von Liebe, Verbundenheit und tiefem Zugehörigkeitsgefühl.',
    'Ich vergebe mir meine Fehler — sie haben mich weiser gemacht.',
    'Ich lasse den Glauben los, dass ich mir meine eigene Liebe verdienen müsste.',
    'Mein Wert ist mir von Natur aus eigen und nichts kann ihn nehmen.',
    'Ich investiere in mich selbst, weil ich weiß, dass ich es wert bin.',
    'Ich spreche freundlich mit mir selbst und weigere mich, mein eigener Kritiker zu sein.',
    'Mein Körper verdient Liebe und Fürsorge in jeder Lebensphase.',
    'Ich sehe meine eigene Schönheit klar und ohne zu zögern.',
    'Ich erlaube mir, Komplimente und Zuneigung mit Anmut anzunehmen.',
    'Ich bin nicht zu viel — ich bin genau genug.',
    'Mein Glück ist genauso wichtig wie das aller anderen.',
    'Ich lasse die Gewohnheit los, mich selbst immer zuletzt zu stellen.',
    'Ich bin jemand, mit dem ich wirklich gerne Zeit verbringe.',
    'Ich liebe, wer ich mit jedem Tag werde.',
    'Mein Wert ist nicht an meine Produktivität oder meine Leistungen geknüpft.',
    'Ich setze Grenzen, weil ich mich selbst zutiefst liebe und respektiere.',
    'Ich wähle Beziehungen, die die Liebe widerspiegeln, die ich für mich selbst empfinde.',
    'Ich erlaube mir, jetzt glücklich zu sein, ohne Bedingungen.',
    'Ich schätze meine Einzigartigkeit und entschuldige mich nicht mehr dafür.',
    'Ich bin die Liebe, nach der ich die ganze Zeit gesucht habe.',
    'Ich schenke mir die Gnade, die ich so leicht anderen entgegenbringe.',
    'Ich halte mich in den schweren Momenten mit Zärtlichkeit.',
    'Meine innere Welt ist ein Ort der Wärme und Akzeptanz.',
    'Ich verdiene ein Leben, das sich innen genauso gut anfühlt, wie es von außen aussieht.',
    'Ich verlasse mich nicht mehr auf Kosten meiner selbst, um andere zu erfreuen.',
    'Selbstliebe ist nicht selbstsüchtig — sie ist notwendig.',
    'Ich ehre meine Heilung als heilig und zutiefst bedeutsam.',
    'Ich wähle, mich selbst durch mitfühlende Augen zu sehen.',
    'Ich darf Raum einnehmen, aufblühen und geliebt werden.',
    'Meine Sensibilität ist eine Stärke, keine Schwäche.',
    'Ich lerne, mich selbst mit jedem Tag ein bisschen mehr zu lieben.',
    'Ich verdiene dieselbe Liebe, die ich so großzügig anderen schenke.',
    'Ich bin zutiefst und bedingungslos meiner eigenen Liebe würdig.',
    'Freundlich zu mir selbst zu sein ist eine tägliche Praxis, zu der ich mich bekenne.',
    'Ich liebe jeden Teil von mir, einschließlich der Teile, die noch heilen.',
    'Ich liebe mich selbst — und das ist mehr als genug, um anzufangen.'
  ]),
  ('cultivate_self_love', 'fr', 200, 'Cultiver l''amour de soi', array[
    'Je mérite mon propre amour et je le donne librement.',
    'Ma relation avec moi-même est la plus importante que j''aie.',
    'Je me traite avec la même bienveillance que j''offre à ceux que j''aime.',
    'Je suis suffisant(e), toujours, sans avoir besoin de le prouver.',
    'Mes besoins comptent et je les honore sans m''en excuser.',
    'Je me choisis chaque jour sans culpabilité.',
    'Être mon(ma) meilleur(e) ami(e) me vient naturellement.',
    'Je mérite de belles choses et je m''autorise à les recevoir.',
    'Je suis doux(douce), patient(e) et compatissant(e) envers moi-même.',
    'Mes imperfections font partie de ce qui me rend magnifiquement humain(e).',
    'Je libère l''autocritique et la remplace par l''autocompassion.',
    'Je suis fier(ère) de qui je suis et du chemin qui m''a façonné(e).',
    'Je me donne la permission de me reposer, de jouer et de simplement profiter de la vie.',
    'Me célébrer n''a pas besoin d''occasion particulière.',
    'Je mérite amour, connexion et appartenance profonde.',
    'Je me pardonne mes erreurs — elles m''ont rendu(e) plus sage.',
    'Je lâche la croyance que je dois mériter mon propre amour.',
    'Ma valeur est innée et rien ne peut me l''enlever.',
    'J''investis en moi parce que je sais que j''en vaux la peine.',
    'Je me parle avec bienveillance et refuse d''être mon propre critique.',
    'Mon corps mérite amour et soin à chaque étape de la vie.',
    'Je vois clairement ma propre beauté, sans hésitation.',
    'Je m''autorise à recevoir compliments et amour avec grâce.',
    'Je ne suis pas trop — je suis exactement ce qu''il faut.',
    'Mon bonheur compte autant que celui des autres.',
    'Je renonce à l''habitude de me passer en dernier.',
    'Je suis quelqu''un avec qui je suis vraiment fier(ère) de passer du temps.',
    'J''aime la personne que je deviens chaque jour qui passe.',
    'Ma valeur n''est pas liée à ma productivité ni à mes réalisations.',
    'Je pose des limites parce que je m''aime et me respecte profondément.',
    'Je choisis des relations qui reflètent l''amour que j''ai pour moi-même.',
    'Je m''autorise à être heureux(se) maintenant, sans conditions.',
    'J''apprécie mon unicité et je cesse de m''en excuser.',
