  ('cultivate_self_love', 'ja', 1100, '自分を慈しむ', array[
    '私は自分の愛に値する存在であり、惜しみなくそれを与えます。',
    '自分自身との関係は、私が持つ最も大切な関係です。',
    '愛する人たちに与えるのと同じ優しさで自分を扱います。',
    '私は十分な存在です――いつでも、何も証明しなくていい。',
    '私のニーズは大切であり、遠慮なくそれを尊重します。',
    '毎日、罪悪感なく自分自身を選びます。',
    '自分の最良の友でいることが自然にできるようになっています。',
    '私は良いことを受け取る価値があり、それを受け入れることを許します。',
    '自分に対して優しく、忍耐強く、思いやりを持っています。',
    '私の欠点は、美しく人間らしい私の一部です。',
    '自己批判を手放し、自己への思いやりに置き換えます。',
    '自分という人間と自分を形作った歩みを誇りに思います。',
    '休み、遊び、ただ人生を楽しむことを自分に許します。',
    '自分を祝うのに特別な理由は必要ありません。',
    '私は愛され、つながり、深く居場所を持つ価値があります。',
    '間違いを自分に許します――それが私をより賢くしてくれました。',
    '自分の愛を稼がなければならないという信念を手放します。',
    '私の価値は本来のものであり、何も奪うことはできません。',
    '自分に投資します――それだけの価値があると知っているから。',
    '自分に優しく語りかけ、自分の批判者になることを拒みます。',
    '私の体は人生のどの段階でも愛と大切にされる価値があります。',
    '自分の美しさをはっきりと、迷わず見つめます。',
    '褒め言葉と愛を優雅に受け取ることを自分に許します。',
    '私は多すぎない――ちょうどいい存在です。',
    '私の幸せは他の誰かのものと同じくらい大切です。',
    '自分を後回しにする習慣を手放します。',
    '自分と過ごす時間を心から誇りに思います。',
    '毎日変化していく自分が好きです。',
    '私の価値は生産性や成果に縛られていません。',
    '自分を愛し、深く尊重しているから、境界線を設けます。',
    '自分に対して持つ愛を映し返してくれる人間関係を選びます。',
    '今すぐ、条件なく幸せになることを自分に許します。',
    '自分の個性を大切にし、それについて謝ることをやめます。',
    '私こそが、ずっと探し求めてきた愛そのものです。',
    '他者には簡単にできる許しを自分にも与えます。',
    '辛い瞬間には、柔らかく自分を抱きしめます。',
    '私の内なる世界は温かさと受け入れに満ちた場所です。',
    '私は内側と同じくらい良いと感じられる人生を生きる価値があります。',
    'もう他者を喜ばせるために自分を見捨てません。',
    '自己愛は利己的ではありません――それは不可欠なものです。',
    '自分の癒しを神聖で深く大切なものとして敬います。',
    '思いやりの目で自分を見ることを選びます。',
    'スペースを取り、花開き、愛されることを自分に許します。',
    '私の繊細さは弱さではなく、強さです。',
    '毎日、自分をもっと深く愛することを学んでいます。',
    '他者に惜しみなく与えるのと同じ愛を、自分も受け取る価値があります。',
    '私は深く、無条件に、自分の愛に値する存在です。',
    '自分に優しくすることは、毎日続ける実践です。',
    'まだ癒えている部分も含め、自分のすべてを愛しています。',
    '自分を愛しています――それだけで十分に始まれます。'
  ]),
