  ('cultivate_self_love', 'zh-hans', 1300, '培养自我关爱', array[
    '我值得自己的爱，我也自由地给予它。',
    '我与自己的关系是我拥有的最重要的一段关系。',
    '我以对待我所爱之人同样的温柔来对待自己。',
    '我已经足够了，始终如此，无需证明任何事。',
    '我的需求是重要的，我不带歉意地尊重它们。',
    '每一天，我都毫无愧疚地选择自己。',
    '成为自己最好的朋友，对我来说是自然而然的。',
    '我值得美好的事物，我也允许自己接受它们。',
    '我对自己温柔、耐心而富有慈悲心。',
    '我的缺点是让我美丽地成为人的一部分。',
    '我放下自我批评，以自我慈悲取而代之。',
    '我为自己是谁，以及塑造我的旅程感到骄傲。',
    '我允许自己休息、玩乐，单纯地享受生活。',
    '庆祝自己不需要任何特殊场合。',
    '我值得爱、联结与深深的归属感。',
    '我原谅自己的错误，它们让我更智慧。',
    '我放下必须赢得自己的爱这一信念。',
    '我的价值是与生俱来的，没有什么能夺走它。',
    '我投资于自己，因为我知道我值得。',
    '我以善意与自己对话，拒绝成为自己的批评者。',
    '在生命的每一个阶段，我的身体都值得被爱与呵护。',
    '我清晰而毫不犹豫地看见自己的美丽。',
    '我优雅地接受赞美与爱。',
    '我不是太多，我恰恰足够。',
    '我的幸福与任何人的幸福同样重要。',
    '我放下总是把自己放在最后的习惯。',
    '我是一个我真正为之骄傲、乐于相伴的人。',
    '我爱着自己每一天都在成为的那个人。',
    '我的价值不与我的生产力或成就挂钩。',
    '我设立边界，因为我深深地爱并尊重自己。',
    '我选择能反映我对自己的爱的关系。',
    '我允许自己现在就幸福，无需任何条件。',
    '我欣赏自己的独特性，不再为它道歉。',
    '我就是我一直在寻找的那份爱。',
    '我给自己我如此轻易地给予他人的宽容。',
    '在艰难的时刻，我温柔地抱持自己。',
    '我的内心世界是一个温暖而被接纳的地方。',
    '我值得一段内在感觉与外在看起来同样美好的生活。',
    '我不再为了取悦他人而抛弃自己。',
    '自爱不是自私，而是必要的。',
    '我尊重自己的疗愈过程，视之为神圣而重要的事。',
    '我选择以慈悲的眼光看待自己。',
    '我被允许占据空间、绽放，并被爱。',
    '我的敏感是一种力量，而非软弱。',
    '我每一天都在学习更完整地爱自己。',
    '我值得我如此慷慨地给予他人的同等的爱。',
    '我深深地、无条件地值得自己的爱。',
    '善待自己是我每天都坚守的修行。',
    '我爱自己的每一部分，包括那些仍在愈合的部分。',
    '我爱自己，这已经足以开始一切。'
  ]),
  ('cultivate_self_love', 'zh-hant', 1400, '培養自我關愛', array[
    '我值得擁有自己的愛，我自由地給予它。',
    '我與自己的關係是我擁有的最重要的關係。',
    '我以對待所愛之人的同樣善意對待自己。',
    '我已經足夠了，永遠如此，不需要證明任何事。',
    '我的需求很重要，我毫不道歉地尊重它們。',
    '我每天都毫無愧疚地選擇自己。',
    '做自己最好的朋友，對我來說是很自然的事。',
    '我值得擁有美好的事物，我允許自己接受它們。',
    '我對自己溫柔、有耐心、充滿慈悲。',
    '我的缺點是讓我成為美麗人類的一部分。',
    '我放下自我批評，以自我慈悲取而代之。',
    '我為自己是誰以及塑造我的旅程感到驕傲。',
    '我給自己休息、玩耍和純粹享受生活的許可。',
    '慶祝自己不需要任何特別的場合。',
    '我值得被愛、被連結，以及深深地歸屬。',
    '我原諒自己的錯誤，它們讓我更有智慧。',
    '我放下了認為自己需要贏得自己的愛的信念。',
    '我的價值是與生俱來的，沒有任何事物能帶走它。',
    '我投資自己，因為我知道自己值得。',
    '我以善意與自己說話，拒絕成為自己的批評者。',
    '在生命的每一個階段，我的身體都值得被愛與照顧。',
    '我清晰而毫不猶豫地看見自己的美麗。',
    '我允許自己優雅地接受讚美和愛。',
    '我並不過多，我恰恰足夠。',
    '我的快樂和任何人的快樂一樣重要。',
    '我放下把自己放在最後的習慣。',
    '我是一個我真心樂意與之共度時光的人。',
    '我愛著每天都在成長的自己。',
    '我的價值不與我的生產力或成就掛鉤。',
    '我設定界限，因為我深深地愛與尊重自己。',
    '我選擇那些反映我對自己之愛的關係。',
    '我允許自己現在就快樂，無需任何條件。',
    '我欣賞自己的獨特性，不再為此道歉。',
    '我就是我一直在尋找的愛。',
    '我給予自己同樣容易給予他人的寬容。',
    '在艱難的時刻，我溫柔地擁抱自己。',
    '我的內心世界是一個充滿溫暖與接納的地方。',
    '我值得擁有一個內心感受與外表一樣美好的生活。',
    '我不再為了取悅他人而拋棄自己。',
    '自愛不是自私，而是必要的。',
    '我將自己的療癒視為神聖而深具意義的事。',
    '我選擇以慈悲的眼光看待自己。',
    '我被允許佔有空間、綻放，並被愛。',
    '我的敏感是一種力量，而非弱點。',
    '我每天都在學習更完整地愛自己。',
    '我值得得到我如此慷慨給予他人的同等愛。',
    '我深刻而無條件地值得自己的愛。',
    '對自己仁慈是我每天都在修行的功課。',
    '我愛自己的每一個部分，包括那些仍在療癒中的部分。',
    '我愛自己，這已經足以開始了。'
