  ('heal_from_past_wounds', 'en', 0, 'Heal past wounds', array[
    'I am healing more deeply with every day that passes.',
    'My past does not predict my future — I do.',
    'I release the pain of the past and step into my freedom.',
    'Healing is happening in me even when I cannot see it.',
    'I give myself full permission to heal at my own pace.',
    'I carry the lessons of my past without carrying the pain.',
    'Forgiving myself is one of the bravest things I do.',
    'I am safe to feel my pain and equally safe to release it.',
    'I am not broken — I am someone who survived and grew.',
    'My wounds are healing and making room for something new.',
    'I release resentment because my peace matters more.',
    'Every day I choose healing over holding on.',
    'I am worthy of love even with every scar I carry.',
    'I honor what I have been through without living there.',
    'I no longer punish myself for things I could not control.',
    'I am becoming whole again, piece by piece, day by day.',
    'I see my wounds as stories of survival, not signs of weakness.',
    'Making peace with my past is something I do gently.',
    'I deserve to heal fully — not just partially, but completely.',
    'I release the beliefs that were never mine to keep.',
    'I am allowed to outgrow the pain that once defined me.',
    'I forgive the younger version of me who did not know better.',
    'I no longer let old pain make decisions for my present life.',
    'I am safe to feel everything I once had to push away.',
    'I am gently and bravely rewriting my own story.',
    'I choose to see my past with compassion rather than shame.',
    'I am free from the grip of what once hurt me.',
    'Healing surprises me in unexpected and beautiful ways.',
    'I am more than what I lost and more than what was taken.',
    'I walk away from what hurt me and toward what heals me.',
    'I give myself what I once needed but did not receive.',
    'I replace old wounds with new wisdom and deeper love.',
    'I allow myself to be seen, even in my most tender places.',
    'I am rebuilding myself with care, patience, and love.',
    'I choose to no longer be a prisoner of my own past.',
    'I release what was never mine to carry and feel lighter.',
    'I am proud of how far I have come on this healing journey.',
    'My future is not shadowed by my past — it is bright.',
    'Old patterns are dissolving — new ways of being are forming.',
    'I give myself compassion for every hard thing I have endured.',
    'My heart is healing and becoming more open, not more closed.',
    'I am safe to love again, trust again, and hope again.',
    'Every breath I take moves healing energy through my body.',
    'I release old versions of my story that no longer serve me.',
    'I am free from what once held me back.',
    'Healing is not linear — I am patient with my own process.',
    'I no longer need the pain to remind me of what I have learned.',
    'I give myself grace for every chapter it took to get here.',
    'My healing is a testament to my incredible strength.',
    'I am free, I am healing, and I am becoming whole.'
  ]),
  ('heal_from_past_wounds', 'de', 100, 'Alte Wunden heilen', array[
    'Ich heile mit jedem Tag tiefer, der vergeht.',
    'Meine Vergangenheit bestimmt nicht meine Zukunft — das tue ich.',
    'Ich lasse den Schmerz der Vergangenheit los und trete in meine Freiheit.',
    'Heilung geschieht in mir, auch wenn ich sie nicht sehen kann.',
    'Ich gebe mir volle Erlaubnis, in meinem eigenen Tempo zu heilen.',
    'Ich trage die Lektionen meiner Vergangenheit, ohne den Schmerz zu tragen.',
    'Mir selbst zu vergeben ist eines der mutigsten Dinge, die ich tue.',
    'Ich darf meinen Schmerz fühlen und bin genauso sicher dabei, ihn loszulassen.',
    'Ich bin nicht zerbrochen — ich bin jemand, der überlebt hat und gewachsen ist.',
    'Meine Wunden heilen und machen Platz für etwas Neues.',
    'Ich lasse Ressentiments los, weil mein Frieden mehr zählt.',
    'Jeden Tag wähle ich Heilung statt Festhalten.',
    'Ich bin liebenswürdig, auch mit jedem Mal, das ich getragen habe.',
    'Ich ehre, was ich durchgemacht habe, ohne dort zu leben.',
    'Ich bestrafe mich nicht mehr für Dinge, die ich nicht kontrollieren konnte.',
    'Ich werde wieder ganz, Stück für Stück, Tag für Tag.',
    'Ich sehe meine Wunden als Geschichten des Überlebens, nicht als Zeichen der Schwäche.',
    'Frieden mit meiner Vergangenheit zu schließen ist etwas, das ich behutsam tue.',
    'Ich verdiene es, vollständig zu heilen — nicht nur teilweise, sondern vollständig.',
    'Ich lasse Glaubenssätze los, die nie meine eigenen waren.',
    'Ich darf über den Schmerz hinauswachsen, der mich einst definierte.',
    'Ich vergebe der jüngeren Version meiner selbst, die es nicht besser wusste.',
    'Ich lasse alten Schmerz nicht mehr Entscheidungen für mein heutiges Leben treffen.',
    'Ich darf alles fühlen, was ich einst wegschieben musste.',
    'Ich schreibe behutsam und mutig meine eigene Geschichte neu.',
    'Ich wähle, meine Vergangenheit mit Mitgefühl statt mit Scham zu betrachten.',
    'Ich bin frei vom Griff dessen, was mich einst verletzt hat.',
    'Heilung überrascht mich auf unerwartete und wunderschöne Weise.',
    'Ich bin mehr als das, was ich verloren habe, und mehr als das, was mir genommen wurde.',
    'Ich gehe weg von dem, was mir wehgetan hat, und hin zu dem, was mich heilt.',
    'Ich gebe mir selbst, was ich einst brauchte aber nicht empfangen habe.',
    'Ich ersetze alte Wunden durch neue Weisheit und tiefere Liebe.',
    'Ich erlaube mir, gesehen zu werden, auch an meinen zartesten Stellen.',
    'Ich baue mich mit Fürsorge, Geduld und Liebe neu auf.',
    'Ich entscheide mich, nicht länger ein Gefangener meiner eigenen Vergangenheit zu sein.',
    'Ich lasse los, was nie meine Last war, und fühle mich leichter.',
    'Ich bin stolz darauf, wie weit ich auf diesem Heilungsweg gekommen bin.',
    'Meine Zukunft wird nicht von meiner Vergangenheit überschattet — sie ist hell.',
    'Alte Muster lösen sich auf — neue Seinsweisen entstehen.',
    'Ich schenke mir Mitgefühl für alles Schwere, das ich durchgestanden habe.',
    'Mein Herz heilt und öffnet sich mehr, nicht weniger.',
    'Ich darf wieder lieben, wieder vertrauen und wieder hoffen.',
    'Mit jedem Atemzug fließt Heilungsenergie durch meinen Körper.',
    'Ich lasse alte Versionen meiner Geschichte los, die mir nicht mehr dienen.',
    'Ich bin frei von dem, was mich einst zurückgehalten hat.',
    'Heilung ist nicht linear — ich bin geduldig mit meinem eigenen Prozess.',
    'Ich brauche den Schmerz nicht mehr, um mich an das Gelernte zu erinnern.',
    'Ich schenke mir Gnade für jedes Kapitel, das nötig war, um hierher zu gelangen.',
    'Meine Heilung ist ein Zeugnis meiner unglaublichen Stärke.',
    'Ich bin frei, ich heile und ich werde ganz.'
  ]),
  ('heal_from_past_wounds', 'fr', 200, 'Guérir les blessures du passé', array[
    'Je guéris plus profondément avec chaque jour qui passe.',
    'Mon passé ne prédit pas mon avenir — c''est moi qui le fais.',
    'Je libère la douleur du passé et j''entre dans ma liberté.',
    'La guérison se produit en moi même quand je ne la vois pas.',
    'Je me donne pleinement la permission de guérir à mon propre rythme.',
    'Je porte les leçons de mon passé sans en porter la douleur.',
    'Me pardonner est l''une des choses les plus courageuses que je fasse.',
    'Je suis en sécurité pour ressentir ma douleur et tout aussi en sécurité pour la libérer.',
    'Je ne suis pas brisé(e) — je suis quelqu''un qui a survécu et qui a grandi.',
    'Mes blessures guérissent et font place à quelque chose de nouveau.',
    'Je libère le ressentiment parce que ma paix compte davantage.',
    'Chaque jour, je choisis la guérison plutôt que l''attachement.',
    'Je suis digne d''amour avec toutes les cicatrices que je porte.',
    'J''honore ce que j''ai traversé sans y vivre.',
    'Je ne me punis plus pour des choses que je ne pouvais pas contrôler.',
    'Je redeviens entier(ère), pièce par pièce, jour après jour.',
    'Je vois mes blessures comme des histoires de survie, non comme des signes de faiblesse.',
    'Faire la paix avec mon passé est quelque chose que je fais en douceur.',
    'Je mérite de guérir pleinement — pas à moitié, mais complètement.',
    'Je libère les croyances qui n''ont jamais été les miennes.',
    'J''ai le droit de dépasser la douleur qui me définissait autrefois.',
    'Je pardonne à la version plus jeune de moi qui ne savait pas mieux.',
    'Je ne laisse plus la vieille douleur prendre des décisions pour ma vie présente.',
    'Je suis en sécurité pour ressentir tout ce que j''ai dû refouler autrefois.',
    'Je réécris doucement et courageusement ma propre histoire.',
    'Je choisis de voir mon passé avec compassion plutôt qu''avec honte.',
    'Je suis libéré(e) de l''emprise de ce qui m''a autrefois blessé(e).',
    'La guérison me surprend de façons inattendues et magnifiques.',
    'Je suis plus que ce que j''ai perdu et plus que ce qui m''a été pris.',
    'Je m''éloigne de ce qui m''a blessé(e) et je m''avance vers ce qui me guérit.',
    'Je me donne ce dont j''avais besoin autrefois sans l''avoir reçu.',
    'Je remplace les vieilles blessures par une nouvelle sagesse et un amour plus profond.',
    'Je m''autorise à être vu(e), même dans mes endroits les plus vulnérables.',
    'Je me reconstruis avec soin, patience et amour.',
    'Je choisis de ne plus être prisonnier(ère) de mon propre passé.',
    'Je libère ce qui n''était pas le mien à porter et je me sens plus léger(ère).',
    'Je suis fier(ère) du chemin parcouru dans ce voyage de guérison.',
    'Mon avenir n''est pas assombri par mon passé — il est lumineux.',
    'Les vieux schémas se dissolvent — de nouvelles façons d''être se forment.',
    'Je me donne de la compassion pour chaque chose difficile que j''ai vécue.',
    'Mon cœur guérit et s''ouvre davantage plutôt que de se fermer.',
    'Je suis en sécurité pour aimer à nouveau, faire confiance à nouveau et espérer à nouveau.',
    'Chaque respiration que je prends fait circuler l''énergie de guérison dans mon corps.',
    'Je libère les vieilles versions de mon histoire qui ne me servent plus.',
    'Je suis libéré(e) de ce qui me retenait autrefois.',
    'La guérison n''est pas linéaire — je suis patient(e) avec mon propre processus.',
    'Je n''ai plus besoin de la douleur pour me rappeler ce que j''ai appris.',
    'Je m''accorde de la grâce pour chaque chapitre qu''il a fallu pour arriver ici.',
    'Ma guérison est le témoignage de ma force incroyable.',
    'Je suis libre, je guéris, et je deviens entier(ère).'
  ]),
  ('heal_from_past_wounds', 'es', 300, 'Sanar heridas del pasado', array[
    'Me estoy sanando más profundamente con cada día que pasa.',
    'Mi pasado no predice mi futuro — lo hago yo.',
    'Suelto el dolor del pasado y entro en mi libertad.',
    'La sanación está ocurriendo en mí incluso cuando no puedo verla.',
    'Me doy pleno permiso para sanar a mi propio ritmo.',
    'Llevo las lecciones de mi pasado sin cargar el dolor.',
    'Perdonarme a mí misma es una de las cosas más valientes que hago.',
    'Estoy a salvo para sentir mi dolor e igualmente a salvo para soltarlo.',
    'No estoy rota — soy alguien que sobrevivió y creció.',
    'Mis heridas están sanando y haciendo espacio para algo nuevo.',
    'Suelto el resentimiento porque mi paz importa más.',
