    'Ya no dejo que el dolor viejo tome decisiones por mi vida presente.',
    'Estoy a salvo para sentir todo lo que una vez tuve que reprimir.',
    'Estoy reescribiendo mi propia historia con gentileza y valentía.',
    'Elijo ver mi pasado con compasión en lugar de vergüenza.',
    'Soy libre del peso de lo que una vez me hirió.',
    'La sanación me sorprende de maneras inesperadas y hermosas.',
    'Soy más que lo que perdí y más que lo que me arrebataron.',
    'Me alejo de lo que me lastimó y me acerco a lo que me sana.',
    'Me doy lo que alguna vez necesité y no recibí.',
    'Reemplazo viejas heridas con nueva sabiduría y amor más profundo.',
    'Me permito ser vista, incluso en mis lugares más tiernos.',
