    'Suelto viejas versiones de mi historia que ya no me sirven.',
    'Soy libre de lo que una vez me detuvo.',
    'La sanación no es lineal — soy paciente con mi propio proceso.',
    'Ya no necesito el dolor para recordarme lo que he aprendido.',
    'Me doy gracia por cada capítulo que me tomó llegar aquí.',
    'Mi sanación es un testimonio de mi increíble fortaleza.',
    'Soy libre, estoy sanando y me estoy volviendo completa.'
  ]),
  ('heal_from_past_wounds', 'it', 400, 'Guarire le ferite del passato', array[
    'Sto guarendo sempre più profondamente con ogni giorno che passa.',
    'Il mio passato non predice il mio futuro — lo faccio io.',
    'Lascio andare il dolore del passato e mi incammino verso la mia libertà.',
    'La guarigione sta avvenendo in me anche quando non riesco a vederla.',
    'Mi do il pieno permesso di guarire al mio ritmo.',
    'Porto con me le lezioni del mio passato senza portare il dolore.',
    'Perdonarmi è una delle cose più coraggiose che faccio.',
    'Sono al sicuro nel sentire il mio dolore e ugualmente al sicuro nel rilasciarlo.',
    'Non sono spezzato — sono qualcuno che è sopravvissuto e cresciuto.',
    'Le mie ferite stanno guarendo e stanno facendo spazio a qualcosa di nuovo.',
    'Lascio andare il risentimento perché la mia pace vale di più.',
    'Ogni giorno scelgo la guarigione invece di aggrapparmi.',
    'Sono degno di amore anche con ogni cicatrice che porto.',
    'Onoro ciò che ho attraversato senza viverci dentro.',
    'Non mi punisco più per cose che non potevo controllare.',
    'Sto tornando integro, pezzo per pezzo, giorno per giorno.',
    'Vedo le mie ferite come storie di sopravvivenza, non come segni di debolezza.',
    'Fare pace con il mio passato è qualcosa che faccio con delicatezza.',
    'Merito di guarire completamente — non solo in parte, ma del tutto.',
    'Lascio andare le convinzioni che non erano mai mie.',
    'Mi è permesso di crescere oltre il dolore che un tempo mi definiva.',
    'Perdono la versione più giovane di me che non sapeva fare di meglio.',
    'Non lascio più che il vecchio dolore prenda decisioni per la mia vita presente.',
    'Sono al sicuro nel sentire tutto ciò che un tempo ho dovuto reprimere.',
    'Sto riscrivendo la mia storia con gentilezza e coraggio.',
    'Scelgo di guardare il mio passato con compassione invece che con vergogna.',
    'Sono libero dalla morsa di ciò che un tempo mi ha ferito.',
    'La guarigione mi sorprende in modi inattesi e meravigliosi.',
    'Sono più di ciò che ho perso e più di ciò che mi è stato tolto.',
    'Mi allontano da ciò che mi ha fatto del male e mi avvicino a ciò che mi guarisce.',
    'Mi do ciò di cui una volta avevo bisogno ma non ho ricevuto.',
    'Sostituisco le vecchie ferite con nuova saggezza e amore più profondo.',
