    'Il mio futuro non è oscurato dal mio passato — è luminoso.',
    'I vecchi schemi si stanno dissolvendo — nuovi modi di essere si stanno formando.',
    'Mi do compassione per ogni cosa difficile che ho sopportato.',
    'Il mio cuore sta guarendo e sta diventando più aperto, non più chiuso.',
    'Sono al sicuro nell''amare di nuovo, fidarmi di nuovo e sperare di nuovo.',
    'Ogni respiro che prendo porta energia guaritrice attraverso il mio corpo.',
    'Lascio andare le vecchie versioni della mia storia che non mi servono più.',
    'Sono libero da ciò che un tempo mi tratteneva.',
    'La guarigione non è lineare — sono paziente con il mio processo.',
    'Non ho più bisogno del dolore per ricordarmi ciò che ho imparato.',
    'Mi do grazia per ogni capitolo che ci è voluto per arrivare qui.',
    'La mia guarigione è una testimonianza della mia incredibile forza.',
    'Sono libero, sto guarendo e sto tornando integro.'
  ]),
  ('heal_from_past_wounds', 'nl', 500, 'Oude wonden helen', array[
    'Ik heel elke dag dieper naarmate de tijd verstrijkt.',
    'Mijn verleden voorspelt mijn toekomst niet — ik doe dat.',
    'Ik laat de pijn van het verleden los en stap in mijn vrijheid.',
    'Genezing vindt in mij plaats, zelfs als ik het niet kan zien.',
    'Ik geef mezelf volledige toestemming om op mijn eigen tempo te helen.',
    'Ik draag de lessen van mijn verleden zonder de pijn te dragen.',
    'Mezelf vergeven is een van de dapperste dingen die ik doe.',
