    'Elke ademhaling die ik neem brengt helende energie door mijn lichaam.',
    'Ik laat oude versies van mijn verhaal los die me niet meer dienen.',
    'Ik ben vrij van wat me ooit tegenhield.',
    'Genezing is niet lineair — ik ben geduldig met mijn eigen proces.',
    'Ik heb de pijn niet meer nodig om me te herinneren wat ik geleerd heb.',
