    'Fazer as pazes com meu passado é algo que faço gentilmente.',
    'Mereço me curar completamente — não apenas parcialmente, mas por inteiro.',
    'Liberto crenças que nunca foram minhas para guardar.',
    'Tenho permissão de superar a dor que um dia me definiu.',
    'Perdoo a versão mais jovem de mim que não sabia mais.',
    'Não deixo mais a dor antiga tomar decisões na minha vida presente.',
    'Estou seguro para sentir tudo que precisei afastar.',
    'Estou gentil e corajosamente reescrevendo minha própria história.',
    'Escolho ver meu passado com compaixão em vez de vergonha.',
    'Estou livre do peso do que uma vez me machucou.',
    'A cura me surpreende de formas inesperadas e lindas.',
    'Sou mais do que o que perdi e mais do que o que me foi tirado.',
    'Me afasto do que me machucou e caminho em direção ao que me cura.',
