    'Estou livre do que um dia me prendeu.',
    'A cura não é linear — sou paciente com meu próprio processo.',
    'Não preciso mais da dor para me lembrar do que aprendi.',
    'Me dou graça por cada capítulo que foi necessário para chegar aqui.',
    'Minha cura é um testemunho da minha força incrível.',
