    'Я даю себе полное разрешение исцеляться в своём собственном ритме.',
    'Я несу уроки прошлого, не неся его боли.',
    'Прощать себя — одно из самых смелых дел, которые я делаю.',
    'Я в безопасности, чтобы чувствовать свою боль, и столь же в безопасности, чтобы её отпустить.',
    'Я не сломлена — я тот, кто выжил и вырос.',
    'Мои раны заживают и освобождают место для чего-то нового.',
    'Я отпускаю обиду, потому что мой покой важнее.',
    'Каждый день я выбираю исцеление вместо того, чтобы держаться.',
    'Я достойна любви со всеми шрамами, которые несу.',
    'Я чту всё, через что прошла, не живя в этом.',
    'Я больше не наказываю себя за то, что не могла контролировать.',
    'Я снова становлюсь целой — кусочек за кусочком, день за днём.',
    'Я вижу свои раны как истории выживания, а не признаки слабости.',
    'Примирение со своим прошлым — это то, что я делаю бережно.',
    'Я заслуживаю исцелиться полностью — не частично, а целиком.',
    'Я отпускаю убеждения, которые никогда не были моими.',
    'Мне позволено перерасти боль, что когда-то меня определяла.',
    'Я прощаю более молодую себя, которая не знала лучшего.',
    'Я больше не позволяю старой боли принимать решения в моей нынешней жизни.',
    'Я в безопасности, чтобы почувствовать всё то, что когда-то пришлось подавить.',
