    'Я выбираю смотреть на своё прошлое с состраданием, а не со стыдом.',
    'Я свободна от власти того, что когда-то причиняло мне боль.',
    'Исцеление удивляет меня неожиданными и прекрасными способами.',
    'Я больше, чем то, что потеряла, и больше, чем то, что у меня взяли.',
    'Я ухожу от того, что причиняло боль, и иду к тому, что исцеляет.',
    'Я даю себе то, в чём нуждалась когда-то, но не получила.',
    'Я заменяю старые раны новой мудростью и более глубокой любовью.',
    'Я позволяю себе быть увиденной, даже в самых нежных своих местах.',
    'Я восстанавливаю себя с заботой, терпением и любовью.',
    'Я выбираю больше не быть пленницей своего прошлого.',
    'Я отпускаю то, что никогда не было моим, и чувствую себя легче.',
    'Я горжусь тем, как далеко прошла в этом пути исцеления.',
    'Моё будущее не омрачено прошлым — оно светлое.',
    'Старые паттерны растворяются — новые способы бытия формируются.',
