    'أصبح كاملًا مرة أخرى، قطعة قطعة، يومًا بيوم.',
    'أرى جراحي قصصًا للنجاة لا علامات للضعف.',
    'المصالحة مع ماضيّ شيء أفعله بلطف.',
    'أستحق الشفاء الكامل، ليس جزئيًا بل تمامًا.',
    'أتحرر من المعتقدات التي لم تكن لي أصلًا.',
    'يُسمح لي بأن أتجاوز الألم الذي كان يُعرّفني ذات مرة.',
