    'أنا أكثر مما فقدته وأكثر مما أُخذ مني.',
    'أمشي بعيدًا عما آلمني ونحو ما يشفيني.',
    'أمنح نفسي ما كنت أحتاجه ذات مرة ولم أحصل عليه.',
    'أستبدل الجراح القديمة بحكمة جديدة وحب أعمق.',
    'أسمح لنفسي بأن أُرى حتى في أكثر أجزائي رقة.',
    'أعيد بناء نفسي بعناية وصبر وحب.',
    'أختار ألا أكون سجينًا لماضيّ بعد الآن.',
    'أتحرر مما لم يكن علي حمله وأشعر بخفة.',
    'أنا فخور بالمسافة التي قطعتها في رحلة الشفاء هذه.',
    'مستقبلي لا يُظلّله ماضيّ، بل هو مشرق.',
    'الأنماط القديمة تتلاشى وطرق جديدة للوجود تتشكّل.',
    'أمنح نفسي الرحمة على كل شيء صعب مررت به.',
    'قلبي يشفى ويصبح أكثر انفتاحًا لا أكثر انغلاقًا.',
    'أنا بأمان للحب مجددًا، للثقة مجددًا، للأمل مجددًا.',
    'كل نفس أتنفسه يحرّك طاقة الشفاء خلال جسدي.',
    'أتحرر من النسخ القديمة من قصتي التي لم تعد تخدمني.',
    'أنا حر مما كان يُقيّدني.',
    'الشفاء ليس خطيًا، أنا صبور مع عمليتي الخاصة.',
    'لم أعد أحتاج إلى الألم لأتذكر ما تعلمته.',
    'أمنح نفسي النعمة على كل فصل استغرقه الأمر للوصول إلى هنا.',
    'شفاءي شهادة على قوتي الاستثنائية.',
    'أنا حر وأشفى وأصبح كاملًا.'
  ]),
  ('heal_from_past_wounds', 'ja', 1100, '過去の傷を癒す', array[
    '毎日が過ぎるにつれ、もっと深く癒されています。',
    '私の過去が私の未来を決めるのではなく、私自身が決めます。',
    '過去の痛みを手放し、自由へと踏み出します。',
    '見えなくても、癒しは私の中で起きています。',
    '自分のペースで癒す許可を自分に完全に与えます。',
    '過去の教訓は持ち続けながら、痛みは手放します。',
    '自分を許すことは、私のする最も勇気ある行為のひとつです。',
    '痛みを感じることも、それを手放すことも、安全にできます。',
    '私は壊れていません――生き延びて成長した人間です。',
    '私の傷は癒えていき、何か新しいものへの場所を作っています。',
    '平和の方が大切だから、恨みを手放します。',
    '毎日、しがみつくのではなく癒しを選びます。',
    '持つすべての傷を持っていても、私は愛される価値があります。',
    '経験したことを称えながらも、そこに生き続けません。',
    'コントロールできなかったことで自分を罰するのをやめました。',
    '少しずつ、日ごとに、再び全体へと戻っています。',
    '傷を弱さの証ではなく、生存の物語として見ます。',
    '過去と和解することを、自分への優しさをもって行います。',
    '完全に癒える価値があります――一部だけでなく、丸ごと。',
    '自分のものではなかった信念を手放します。',
    'かつて自分を定義していた痛みを超えて成長することを許します。',
    '知らなかったかつての自分を許します。',
    '古い痛みに今の生活を左右させません。',
    'かつて押しやらなければならなかったすべてを感じることが安全にできます。',
    '自分の物語を静かに、勇気をもって書き直しています。',
    '恥ではなく思いやりをもって過去を見ることを選びます。',
    'かつて傷つけたものの呪縛から自由です。',
    '癒しは思いがけない美しい形で驚かせてくれます。',
    '失ったものよりも、奪われたものよりも、大きな存在です。',
    '傷つけたものから離れ、癒してくれるものへ向かいます。',
    'かつて必要だったけれど受け取れなかったものを、自分に与えます。',
    '古い傷を新しい知恵と深い愛に置き換えます。',
    '最も柔らかい部分でも、見てもらうことを自分に許します。',
    '丁寧さと忍耐と愛をもって自分を再建しています。',
    'もう自分の過去の囚人でいることを選びません。',
    '本来自分のものでなかった荷物を手放し、軽くなります。',
    'この癒しの旅でここまで来た自分を誇りに思います。',
    '私の未来は過去に影を落とされていません――明るく輝いています。',
    '古いパターンは溶けていき、新しいあり方が形成されています。',
    '乗り越えてきたすべてに、自分への思いやりを与えます。',
    '私の心は癒え、閉じるのではなく開いていきます。',
    'また愛すること、信じること、希望を持つことが安全にできます。',
    '息をするたびに癒しのエネルギーが体を流れます。',
    'もう役立たなくなった物語の古いバージョンを手放します。',
    'かつて足かせだったものから自由です。',
    '癒しは直線的ではありません――自分のプロセスに忍耐強くあります。',
    '学んだことを思い出すために痛みを必要としなくなりました。',
    'ここに来るまでのすべての章に、自分への恵みを与えます。',
    '私の癒しは自分の驚くべき強さの証です。',
    '私は自由で、癒えていて、全体へと戻っています。'
  ]),
  ('heal_from_past_wounds', 'ko', 1200, '지난 상처 치유하기', array[
