    '나는 매일 치유를 선택합니다, 집착하는 것 대신.',
    '나는 내가 지니고 있는 모든 흉터에도 불구하고 사랑받을 자격이 있습니다.',
    '나는 내가 겪어온 것을 존중하되 그 안에 살지는 않습니다.',
    '나는 더 이상 내가 통제할 수 없었던 것들 때문에 나 자신을 벌하지 않습니다.',
