  ('heal_from_past_wounds', 'zh-hans', 1300, '疗愈过往的伤痛', array[
    '每一天过去，我都在更深地愈合。',
    '我的过去不能预测我的未来，只有我可以。',
    '我释放过去的痛苦，踏入自己的自由。',
    '即使看不见，疗愈也在我内心发生。',
    '我给自己完全的许可，以自己的节奏疗愈。',
    '我承载着过去的教训，而不承载其中的痛苦。',
    '原谅自己是我所做过的最勇敢的事之一。',
    '我可以安全地感受我的痛苦，也同样安全地释放它。',
    '我没有破碎，我是一个经历过并成长了的人。',
    '我的伤口在愈合，为新的事物腾出空间。',
    '我释放怨恨，因为我的平静比它更重要。',
    '每一天，我都选择疗愈而非执着。',
    '即使带着每一道伤痕，我依然值得被爱。',
    '我尊重自己所经历的一切，而不活在其中。',
    '我不再惩罚自己那些我无法控制的事。',
    '我一点一点、一天一天地重新变得完整。',
    '我把自己的伤口看作生存的故事，而非软弱的标志。',
    '与我的过去和解，是我温柔地去做的事。',
    '我值得完全地疗愈，不是部分，而是彻底地。',
    '我释放那些从不属于我的信念。',
    '我被允许超越曾经定义我的痛苦。',
    '我原谅那个不知道得更多的年轻的自己。',
    '我不再让旧日的痛苦为我现在的生活做决定。',
    '我可以安全地感受我曾经不得不压抑的一切。',
    '我轻柔而勇敢地重写自己的故事。',
    '我选择以慈悲而非羞耻来看待我的过去。',
    '我从曾经伤害过我的事物的束缚中解脱了。',
    '疗愈以意想不到且美丽的方式令我惊喜。',
    '我不仅仅是我所失去的，也不仅仅是曾被夺走的。',
    '我离开伤害我的，走向疗愈我的。',
    '我给予自己曾经需要却未曾得到的。',
    '我用新的智慧和更深的爱取代旧日的伤痕。',
    '我允许自己被看见，即使在最柔软脆弱的地方。',
    '我以关怀、耐心与爱重建自己。',
    '我选择不再做自己过去的囚徒。',
    '我放下从不属于我承担的重量，感到更轻盈。',
    '我为自己在这段疗愈旅程中走了多远而感到骄傲。',
    '我的未来不被我的过去所遮蔽，它是光明的。',
    '旧有的模式正在消融，新的存在方式正在形成。',
    '我为自己经历过的每一件艰难的事给予自己慈悲。',
    '我的心正在愈合，变得越来越开放，而非更加封闭。',
    '我可以安全地再次去爱、再次去信任、再次去希望。',
    '每一次呼吸都将疗愈的能量流遍我的全身。',
    '我释放那些不再服务于我的旧日故事。',
    '我从曾经束缚我的一切中自由了。',
    '疗愈不是线性的，我对自己的过程保持耐心。',
    '我不再需要痛苦来提醒我所学到的。',
    '我为走到这里所经历的每一个章节给予自己宽容。',
    '我的疗愈是对我非凡力量的见证。',
    '我自由、我在疗愈，我正在变得完整。'
  ]),
  ('heal_from_past_wounds', 'zh-hant', 1400, '療癒過往傷痛', array[
    '我每過一天都在更深地療癒。',
    '我的過去無法預測我的未來，我才是那個人。',
    '我釋放過去的痛苦，踏入自己的自由。',
    '療癒正在我身上發生，即使我看不見它。',
    '我給予自己完全的許可，以自己的節奏療癒。',
    '我帶著過去的教訓，卻不帶著它的痛苦。',
    '原諒自己是我所做的最勇敢的事之一。',
    '我可以安全地感受自己的痛，也同樣安全地釋放它。',
    '我並沒有破損，我是一個曾經歷磨難並從中成長的人。',
    '我的傷口正在癒合，正在為新的事物騰出空間。',
    '我放下怨恨，因為我的平靜比什麼都重要。',
    '每一天我都選擇療癒，而非緊抓不放。',
    '即使帶著每一道傷疤，我也值得被愛。',
    '我尊重自己經歷過的一切，但不在那裡久居。',
    '我不再為自己無法控制的事懲罰自己。',
    '我正在一點一點、一天一天地重新變得完整。',
    '我將傷口視為倖存的故事，而非軟弱的象徵。',
    '與自己的過去和解，是我溫柔地去做的事。',
    '我值得完全療癒，不是部分地，而是徹底地。',
    '我放下那些從來就不屬於我的信念。',
    '我被允許超越曾經定義我的痛苦。',
    '我原諒不知道更多的年輕的自己。',
    '我不再讓舊日的痛苦為我現在的生活做決定。',
    '我可以安全地感受那些曾經不得不壓抑的一切。',
    '我正在溫柔而勇敢地改寫自己的故事。',
    '我選擇以慈悲而非羞恥看待自己的過去。',
    '我從曾經傷害我的事物的掌控中自由了。',
    '療癒以意想不到的美麗方式讓我驚喜。',
    '我不止於失去的，也不止於被奪走的。',
    '我遠離傷害我的事，走向療癒我的事。',
    '我給予自己曾經需要卻未曾得到的東西。',
    '我以新的智慧和更深的愛取代舊日的傷痕。',
    '我允許自己被看見，即使在最脆弱的地方。',
    '我以關愛、耐心和愛重建自己。',
    '我選擇不再是自己過去的囚徒。',
    '我放下那些本不是我應承擔的，感覺更加輕盈。',
    '我為在這段療癒旅程上走了這麼遠而感到驕傲。',
    '我的未來不被過去所遮蔽，它是光明的。',
    '舊有的模式正在消解，新的存在方式正在成形。',
    '我對自己承受過的每一件難事給予慈悲。',
    '我的心正在療癒，變得越來越開放，而非封閉。',
    '我可以安全地再次愛、再次信任、再次希望。',
    '我的每一次呼吸都讓療癒的能量流過全身。',
    '我放下那些不再對我有益的舊故事。',
    '我從曾經束縛我的事物中解脫出來。',
    '療癒不是線性的，我對自己的過程保持耐心。',
    '我不再需要痛苦來提醒自己學到了什麼。',
    '我為每一個讓我走到這裡的篇章給予自己寬容。',
    '我的療癒是我無比力量的見證。',
    '我是自由的、是療癒中的、我正在變得完整。'
  ]),
  ('improve_my_health', 'en', 0, 'Improve my health', array[
