    'Rest is productive — I give my body what it needs.',
    'I trust my body''s wisdom to find balance and wellness.',
    'My energy is high because I take care of myself inside out.',
    'I prioritize sleep because I know how deeply it restores me.',
    'Staying hydrated and breathing deeply are acts of self-love.',
    'I am in tune with my body and I honor every signal it sends.',
    'I choose habits that build the life and body I love.',
    'I am patient with my body and celebrate every small win.',
    'Showing up for my health is an act of self-respect.',
