    'Отдых продуктивен — я даю телу то, что ему нужно.',
    'Я доверяю мудрости своего тела в поиске баланса и здоровья.',
    'У меня высокая энергия, потому что я забочусь о себе изнутри и снаружи.',
    'Я ставлю сон в приоритет, зная, как глубоко он восстанавливает меня.',
    'Пить воду и дышать глубоко — это акты любви к себе.',
    'Я в гармонии со своим телом и чту каждый сигнал, который оно посылает.',
    'Я выбираю привычки, которые строят жизнь и тело, которые я люблю.',
    'Я терпелива к своему телу и отмечаю каждую маленькую победу.',
    'Заботиться о своём здоровье — это акт самоуважения.',
    'Моё тело прекрасно откликается на любовь, которую я ему даю.',
