    'Находить время для здоровья всегда стоит того.',
    'Я дышу глубоко и даю телу кислород, которого оно жаждет.',
    'Я благодарна за каждый шаг, каждый вдох, каждое биение сердца.',
    'Моё тело — чудо, и я никогда не принимаю его как должное.',
    'Я исцеляюсь изнутри, клетка за клеткой.',
    'Я подхожу к своему здоровью с последовательностью и самосостраданием.',
    'Я просыпаюсь свежей, восстановленной и готовой к дню.',
    'Моё психическое здоровье получает такую же заботу, как и физическое.',
    'Я снимаю стресс со своего тела каждым осознанным вдохом.',
    'Я наращиваю силу, выносливость и уверенность с каждым днём.',
    'Я питаю своё тело с намерением и обращаюсь с ним как со священным.',
