    '与える愛に対して体は美しく応えます。',
    '喜びとエネルギーをもたらす動きを選びます。',
    'もはや健康をサポートしない古い習慣を手放します。',
    '私の体は回復力があり、軽やかに優雅に回復します。',
    '一日ずつ、最も健康な自分へなっています。',
