  ('improve_my_health', 'zh-hans', 1300, '改善我的健康', array[
    '我为自己的身体以及它为我所做的一切深深感恩。',
    '我的身体强壮、有能力，充满活力。',
    '我以爱、好的食物和运动滋养我的身体。',
    '倾听我的身体对我来说是自然而然的事。',
    '我的健康是我最大的财富，我每天都在投资它。',
    '我做出的每一个健康选择都是给未来自己的礼物。',
    '我的身体自然地疗愈，我全力支持这个过程。',
    '我活动身体是因为我爱它，而非惩罚它。',
    '我选择让我充满活力、感到鲜活的食物。',
    '我的身体是我的家，我以深深的尊重对待它。',
    '我每一天都在变得更强壮、更充满生机。',
    '休息是有效的，我给予我的身体它所需要的。',
    '我信任身体的智慧，让它找到平衡与健康。',
    '我的能量充沛，因为我由内而外地照顾自己。',
    '我优先保证睡眠，因为我深知它如何深深地修复我。',
    '保持水分充足和深呼吸都是自爱的行为。',
    '我与我的身体同频，尊重它发出的每一个信号。',
    '我选择能构建我所热爱的生活和身体的习惯。',
    '我对身体保持耐心，庆祝每一个小小的胜利。',
    '为自己的健康出现是一种自我尊重的行为。',
    '我的身体对我给予它的爱产生了美好的回应。',
    '我选择带来喜悦和活力的运动方式。',
    '我放下那些不再支持我健康的旧习惯。',
    '我的身体有韧性，以从容与优雅恢复。',
    '我一天一天地成为最健康的自己。',
    '因为我善待自己的身体，所以我在其中感觉良好。',
    '为自己的健康腾出时间永远是值得的。',
    '我深呼吸，给予身体它渴望的氧气。',
    '我感恩每一步、每一次呼吸、每一下心跳。',
    '我的身体是一个奇迹，我从不将它视为理所当然。',
    '我正在由内而外、细胞一个一个地愈合。',
    '我以一致性和自我慈悲的态度对待我的健康。',
    '我醒来感到神清气爽、元气恢复，为新的一天准备好了。',
    '我的心理健康与我的身体健康得到同等的关怀。',
    '我以每一次有意识的呼吸释放身体里的压力。',
    '我每天都在构建力量、耐力和自信。',
    '我以意图滋养我的身体，以神圣之心对待它。',
    '健康对我来说感觉自然而充满喜悦。',
    '我的活力随着我做出的每一个积极选择而增长。',
    '无论如何，我都致力于为自己的健康出现。',
    '在生命的每一个阶段，我的身体都值得被爱与呵护。',
    '当身体需要休息时，我对它温柔。',
    '我在坚定地承诺让自己感受到最佳状态。',
    '照顾自己是我最重要的工作。',
    '在身体旅程的每一个阶段，我都与它和平共处。',
    '我放下完美主义，拥抱持续的努力。',
    '我的身体知道如何健康，我全力支持它。',
    '我值得感到充满活力、生机勃勃、完全鲜活。',
    '今天每一个好的选择都是对明天的投资。',
    '我健康、我强壮，我为这副身体感恩。'
  ]),
  ('improve_my_health', 'zh-hant', 1400, '改善我的健康', array[
