    '我每天醒來感到神清氣爽、元氣恢復、準備迎接新的一天。',
    '我的心理健康得到與生理健康同等的關照。',
    '我以每一次有意識的呼吸從身體中釋放壓力。',
    '我每天都在建立力量、耐力和自信。',
    '我以意圖滋養我的身體，並將其視為神聖。',
