  ('embrace_growth', 'de', 100, 'Wachstum annehmen', array[
    'Ich wachse immer, ich entwickle mich immer, ich werde immer mehr.',
    'Veränderung ist nichts, das ich fürchte — es ist etwas, das ich willkommen heiße.',
    'Ich bin nicht mehr derselbe Mensch wie vor einem Jahr und ich liebe das.',
    'Meine Komfortzone erweitert sich jeden einzelnen Tag.',
    'Jede Erfahrung in meinem Leben lehrt mich etwas Wertvolles.',
    'Ich bin neugierig auf den Menschen, der ich werde, und freue mich, es herauszufinden.',
    'Die alte Version von mir loszulassen macht Platz für jemanden noch Besseres.',
    'Ich bin immer nur eine Entscheidung von einem völlig anderen Leben entfernt.',
    'Schwierigkeiten bringen immer etwas Wertvolles mit sich.',
    'Wachstum ist mein natürlicher Zustand und ich ergebe mich ihm vollständig.',
    'Ich werde jeden Tag selbstbewusster und lebendiger.',
    'Ich feiere, wie sehr ich mich verändert habe und wie sehr ich mich noch verändere.',
    'Wachstum dem Komfort vorzuziehen wird mir zur zweiten Natur.',
    'Jedes Kapitel meines Lebens bereitet mich auf das nächste vor.',
    'Ich bin geduldig mit meiner eigenen Verwandlung — große Dinge brauchen Zeit.',
    'Ich bleibe offen für Perspektiven, die ich noch nicht entdeckt habe.',
    'Ich fürchte mich nicht davor, wer ich werden könnte, wenn ich mich wachsen lasse.',
    'In meine persönliche Entwicklung zu investieren lohnt sich immer.',
    'Ich umarme den unordentlichen, unvollkommenen, wunderschönen Prozess des Werdens.',
    'Jeden Tag gibt es etwas Neues zu lernen und zu entdecken.',
    'Neu anzufangen ist kein Versagen — es ist Weisheit in Aktion.',
    'Ich wachse in eine Version meiner selbst, die ich immer erträumt habe.',
    'Meine Entwicklung entfaltet sich in genau dem richtigen Tempo.',
    'Lesen, Nachdenken und Üben macht mich zu dem, was ich bin.',
    'Ich erweitere mich auf Arten, die ich mir vor einem Jahr nicht hätte vorstellen können.',
    'Meine härtesten Momente haben mir mein größtes Wachstum geschenkt.',
    'Mit jedem Jahr werde ich mehr ich selbst, nicht weniger.',
    'Über alte Versionen meiner selbst hinauszuwachsen ist etwas, das ich feiere.',
    'Ich gehe mein Leben mit einem Anfängergeist und einem offenen Herzen an.',
    'Ich wachse durch das, was ich durchmache — immer.',
    'Meine persönliche Entwicklung ist ein tägliches Bekenntnis, das ich einhalte.',
    'Ein Werk in Entstehung zu sein ist etwas, worauf ich stolz bin.',
    'Ich entdecke jeden einzelnen Tag neue Stärken in mir.',
    'Fortschritt geschieht immer, auch wenn ich ihn nicht sehen kann.',
    'Die beste Version von mir liegt noch vor mir — und ich freue mich darauf.',
    'Neue Anfänge erfüllen mich mit Begeisterung, nicht mit Angst.',
    'Jeder Rückschlag ist eine Vorbereitung auf etwas noch Größeres.',
    'Ich werde jeden Tag weiser, stärker und widerstandsfähiger.',
    'Nicht alles durchschaut zu haben ist vollkommen in Ordnung.',
    'Ich bin zutiefst dem langen Spiel meines eigenen Werdens verpflichtet.',
    'Wachstum ist selten linear — ich bin geduldig mit dem Prozess.',
    'Ich lasse ab, was mir nicht mehr dient, mit Anmut und Leichtigkeit.',
    'Jede Version von mir hat mich dieser hier ein Stück näher gebracht.',
    'Ich dehne mich über meine Grenzen hinaus, weil dort Wachstum lebt.',
    'Ich bin nicht zurück — ich bin genau pünktlich für meinen eigenen Weg.',
    'Ich wachse in Liebe, in Weisheit und in Freude mit jedem Tag.',
    'Kleine Veränderungen und stille Verwandlungen verdienen es, gefeiert zu werden.',
    'Ich vertraue der Entfaltung meines eigenen einzigartigen Weges.',
    'Ich entwickle mich zu allem, was ich immer sein sollte.',
    'Ich wachse, ich strahle und ich werde ganz.'
  ]),
  ('embrace_growth', 'fr', 200, 'Accueillir la croissance', array[
    'Je grandis toujours, j''évolue toujours, je deviens toujours davantage.',
    'Le changement n''est pas quelque chose que je crains — c''est quelque chose que j''accueille.',
    'Je ne suis plus la même personne qu''il y a un an et j''adore ça.',
    'Ma zone de confort s''élargit chaque jour.',
    'Chaque expérience de ma vie m''enseigne quelque chose de précieux.',
    'Je suis curieux(se) de qui je suis en train de devenir et enthousiaste à l''idée de le découvrir.',
    'Laisser partir l''ancien moi fait place à quelqu''un de encore meilleur.',
    'Je ne suis qu''à une décision d''une vie complètement différente.',
    'La difficulté apporte toujours quelque chose de précieux avec elle.',
    'La croissance est mon état naturel et je m''y abandonne pleinement.',
    'Je deviens plus conscient(e) de moi-même et plus vivant(e) chaque jour.',
    'Je célèbre combien j''ai changé et combien je suis encore en train de changer.',
    'Choisir la croissance plutôt que le confort devient une seconde nature pour moi.',
    'Chaque chapitre de ma vie me prépare pour le suivant.',
    'Je suis patient(e) avec ma propre transformation — les grandes choses prennent du temps.',
