    'Лучшая версия меня ещё впереди — и я в предвкушении.',
    'Новые начала наполняют меня воодушевлением, а не страхом.',
    'Каждая неудача — подготовка к чему-то ещё более великому.',
    'Я становлюсь мудрее, сильнее и более стойкой с каждым днём.',
    'Не иметь всего разложенного по полочкам — это совершенно нормально.',
    'Я глубоко привержена долгой игре своего собственного становления.',
    'Рост редко бывает линейным — я терпелива к процессу.',
    'Я сбрасываю то, что больше не служит мне, с изяществом и лёгкостью.',
    'Каждая версия меня приближала меня к этой.',
    'Я выхожу за пределы своих ограничений, потому что именно там живёт рост.',
    'Я не опоздала — я в точно нужное время для своего пути.',
    'Я расту в любви, мудрости и радости с каждым днём.',
    'Маленькие сдвиги и тихие трансформации заслуживают быть отмеченными.',
    'Я доверяю разворачиванию своего уникального пути.',
    'Я развиваюсь в всё, чем всегда была призвана стать.',
    'Я расту, я сияю, и я становлюсь целой.'
  ]),
  ('embrace_growth', 'tr', 900, 'Büyümeyi kucakla', array[
    'Hep büyüyor, hep gelişiyor, hep daha fazlası olmaya devam ediyorum.',
    'Değişim, korktuğum bir şey değil — hoş karşıladığım bir şey.',
