  ('embrace_growth', 'ar', 1000, 'احتضن النمو', array[
    'أنا دائمًا أنمو وأتطور وأصبح أكثر.',
    'التغيير ليس شيئًا أخشاه، بل شيء أرحّب به.',
    'أنا لست الشخص نفسه الذي كنته قبل عام وأحب ذلك.',
    'منطقة راحتي تتوسع كل يوم.',
    'كل تجربة في حياتي تعلّمني شيئًا قيّمًا.',
    'أنا فضولي بشأن من أصبح عليه ومتحمس لاكتشاف ذلك.',
    'التخلي عن النسخة القديمة مني يفسح المجال لشخص أفضل.',
    'أنا دائمًا على بُعد قرار واحد من حياة مختلفة تمامًا.',
    'الصراع يأتي دائمًا بشيء قيّم معه.',
    'النمو حالتي الطبيعية وأستسلم له بالكامل.',
    'أصبح أكثر وعيًا بالذات وأكثر حياة كل يوم.',
    'أحتفل بكم تغيّرت وبكم لا أزال أتغيّر.',
    'اختيار النمو على الراحة يصبح أمرًا بديهيًا.',
    'كل فصل من حياتي يُهيّئني للفصل القادم.',
    'أنا صبور مع تحولي الخاص، الأشياء العظيمة تأخذ وقتها.',
    'أبقى منفتحًا على وجهات نظر لم أكتشفها بعد.',
    'لا أخشى من أصبح عليه إن سمحت لنفسي بالنمو.',
    'الاستثمار في نموّي الشخصي يستحق دائمًا.',
    'أحتضن العملية الفوضوية وغير المثالية والجميلة للتحوّل.',
    'كل يوم يجلب شيئًا جديدًا للتعلم والاكتشاف.',
    'البداية من جديد ليست فشلًا، بل هي الحكمة في العمل.',
    'أنمو لأكون نسخة من نفسي كنت أحلم بها دائمًا.',
    'تطوّري يتكشّف بالوتيرة الصحيحة تمامًا.',
    'القراءة والتأمل والتمرين تجعلني من أنا.',
    'أتوسّع بطرق لم أكن أتخيّلها قبل عام.',
    'أصعب لحظاتي منحتني أعظم نموّ لديّ.',
    'أصبح أكثر ذاتي لا أقل مع كل عام.',
    'تجاوز النسخ القديمة من نفسي شيء أحتفل به.',
    'أتعامل مع حياتي بعقل المبتدئ وقلب منفتح.',
    'أنمو من خلال ما أمرّ به، دائمًا.',
    'تطوّري الشخصي هو التزام يومي أُوفي به.',
    'أن أكون عملًا قيد التقدم شيء أفخر به.',
    'أكتشف نقاط قوة جديدة في نفسي كل يوم.',
    'التقدم يحدث دائمًا حتى حين لا أستطيع رؤيته.',
    'أفضل نسخة مني لا تزال أمامي وأنا متحمس.',
    'البدايات الجديدة تملأني بالإثارة لا الخوف.',
    'كل نكسة هي إعداد لشيء أعظم.',
    'أصبح أكثر حكمة وقوة ومرونة كل يوم.',
    'ألا أكون قد فهمت كل شيء بعد أمر مقبول تمامًا.',
    'أنا ملتزم بعمق بلعبة التطوّر الطويلة الأمد.',
    'النمو نادرًا ما يكون خطيًا وأنا صبور مع العملية.',
    'أتخلص مما لم يعد يخدمني بأناقة ويسر.',
    'كل نسخة مني أوصلتني إلى هذه النسخة.',
    'أتمدد ما وراء حدودي لأن هناك يسكن النمو.',
    'أنا لست متأخرًا، أنا في الموعد المحدد تمامًا لرحلتي الخاصة.',
    'أنمو في الحب والحكمة والبهجة مع كل يوم يمر.',
    'التحولات الصغيرة والتغييرات الهادئة تستحق الاحتفال.',
    'أثق في تكشّف مسيرتي الفريدة.',
    'أتطور لأكون كل ما كنت مُقدَّرًا أن أكونه.',
    'أنا أنمو وأتألق وأصبح كاملًا.'
  ]),
  ('embrace_growth', 'ja', 1100, '成長を受け入れる', array[
    '私はいつも成長し、進化し、より多くのものへなり続けています。',
    '変化は恐れるものではなく、歓迎するものです。',
    '一年前とは違う自分になっていて、それが好きです。',
    '私のコンフォートゾーンは毎日広がっています。',
    '人生のあらゆる経験が大切なことを教えてくれています。',
    'なりつつある自分に好奇心を感じ、わかっていくのが楽しみです。',
    '古い自分を手放すことで、さらに良い誰かのための場所ができます。',
    '私はいつも一つの決断で全く違う人生から一歩の距離にいます。',
    'もがきはいつも何か価値あるものを連れてきます。',
    '成長は私の自然な状態であり、それに完全に身を任せます。',
    '毎日、より自己認識を深め、より生き生きとなっています。',
    'どれほど変わったか、そして今もまだ変わり続けているかを祝います。',
    '快適さよりも成長を選ぶことが第二の本能になっています。',
    '人生のすべての章が次の章への準備をしてくれています。',
    '自分の変容に忍耐強くあります――素晴らしいものには時間がかかります。',
    'まだ発見していない視点に開かれていられます。',
    '成長を許せばなりうる自分を恐れていません。',
    '自分の個人的成長への投資は常に価値があります。',
    '複雑で不完全で美しいなりゆきのプロセスを受け入れます。',
    '毎日、学び発見できる何か新しいことがあります。',
    '最初からやり直すことは失敗ではなく、行動する知恵です。',
    'ずっと夢見てきた自分のバージョンへ成長しています。',
    '私の進化はちょうど良いペースで展開しています。',
    '読み、振り返り、実践することが私という人間を作ります。',
    '一年前には想像もできなかった方向へ広がっています。',
    '最も辛い瞬間が最大の成長をもたらしてくれました。',
    '年を重ねるごとに、より多くではなくより自分らしくなっています。',
    '古いバージョンの自分を超えていくことを祝います。',
    '初心者の心と開かれた心で自分の人生に向き合います。',
    '経験を通じて成長します――いつでも。',
    '自分の個人的な進化は毎日続けるコミットメントです。',
    '進行中の作品であることは誇らしいことです。',
    '毎日自分の中に新しい強さを発見します。',
    '見えなくても、進歩はいつも起きています。',
    '最良の自分はまだこれからです――そしてわくわくしています。',
    '新しい始まりは恐れではなく、わくわくで満たしてくれます。',
    'すべての挫折は、さらに大きな何かへのセットアップです。',
    '毎日、より賢く、より強く、より回復力のある自分になっています。',
    'すべてを把握していなくても、全く問題ありません。',
    '自分という存在のロングゲームに深くコミットしています。',
    '成長はめったに直線的ではありません――プロセスに忍耐強くあります。',
    'もはや役立たないものを恵みと軽やかさをもって手放しています。',
    'すべての自分のバージョンが今の私に近づかせてくれました。',
    '限界を超えて伸びます――そこに成長が生きているから。',
    '私は遅れていません――自分だけの旅にちょうど間に合っています。',
    '毎日、愛の中で、知恵の中で、喜びの中で成長します。',
    '小さな変化や静かな変容は祝われる価値があります。',
    '自分だけの唯一の道の展開を信頼します。',
    'ずっとなるべき存在へと進化しています。',
    '私は成長し、輝き、全体へとなっています。'
  ]),
  ('embrace_growth', 'ko', 1200, '성장 받아들이기', array[
    '나는 언제나 성장하고, 진화하며, 더 많은 것이 되어가고 있습니다.',
