    '어려움은 언제나 가치 있는 무언가를 함께 가져옵니다.',
    '성장은 나의 자연스러운 상태이며 나는 그것에 온전히 몸을 맡깁니다.',
    '나는 매일 더 자기 인식이 높아지고 더 살아 있어지고 있습니다.',
    '나는 내가 얼마나 변했는지, 그리고 여전히 얼마나 변하고 있는지를 축하합니다.',
    '안락함보다 성장을 선택하는 것은 점점 나의 본성이 되어가고 있습니다.',
    '내 삶의 모든 챕터는 다음을 위해 나를 준비시키고 있습니다.',
    '나는 나 자신의 변화에 인내심을 갖습니다 — 위대한 것들은 시간이 필요합니다.',
