    '나의 개인적인 성장에 투자하는 것은 항상 그만한 가치가 있습니다.',
    '나는 변화의 지저분하고, 불완전하고, 아름다운 과정을 받아들입니다.',
    '매일 새롭게 배우고 발견할 것들이 있습니다.',
    '다시 시작하는 것은 실패가 아닙니다 — 그것은 행동 속의 지혜입니다.',
    '나는 내가 항상 꿈꿔온 나 자신의 버전으로 성장해 가고 있습니다.',
    '나의 진화는 정확히 올바른 속도로 펼쳐지고 있습니다.',
    '읽고, 성찰하고, 실천하는 것이 나를 나로 만듭니다.',
    '나는 1년 전에는 상상할 수 없었던 방식으로 확장되고 있습니다.',
    '나의 가장 힘들었던 순간들이 나에게 가장 큰 성장을 주었습니다.',
    '나는 매년 더 많은 나 자신이 되어가고 있습니다, 덜이 아니라.',
