    '나의 개인적인 진화는 내가 매일 지키는 약속입니다.',
    '진행 중인 작업이라는 것은 내가 자랑스럽게 여기는 것입니다.',
    '나는 매일 내 안에서 새로운 강점을 발견합니다.',
    '전진은 내가 볼 수 없을 때도 항상 일어나고 있습니다.',
    '나의 최상의 버전은 여전히 앞에 있습니다 — 그리고 나는 기대됩니다.',
    '새로운 시작은 두려움이 아닌 설렘으로 나를 채웁니다.',
    '모든 좌절은 더 위대한 무언가를 위한 발판입니다.',
    '나는 매일 더 현명하고, 강하며, 회복력 있게 되어가고 있습니다.',
    '모든 것을 파악하지 못해도 완전히 괜찮습니다.',
    '나는 나 자신의 성장이라는 긴 여정에 깊이 헌신합니다.',
    '성장은 좀처럼 선형적이지 않습니다 — 나는 과정에 인내심을 갖습니다.',
