  ('embrace_growth', 'zh-hans', 1300, '拥抱成长', array[
    '我始终在成长、在进化、在成为更多。',
    '改变不是我恐惧的，而是我欢迎的。',
    '我与一年前不是同一个人了，我喜欢这一点。',
    '我的舒适区每一天都在扩展。',
    '我生命中的每一次经历都在教我一些有价值的东西。',
    '我对自己正在成为谁感到好奇，也为发现这一点而兴奋。',
    '放下旧日的自己，为更好的人腾出了空间。',
    '我永远只需一个决定，就能拥有一段截然不同的生活。',
    '挣扎总是随之带来有价值的东西。',
    '成长是我本来的状态，我完全臣服于它。',
    '我每天都变得更有自我觉察，更加鲜活。',
    '我庆祝自己改变了多少，也庆祝自己仍在改变。',
    '选择成长而非舒适，正在成为我的第二天性。',
    '我生命中的每一个章节都在为下一个做准备。',
    '我对自己的转化保持耐心，伟大的事物需要时间。',
    '我对尚未发现的视角保持开放。',
    '我不害怕如果让自己成长，我可能会成为谁。',
    '投资于自我成长永远是值得的。',
    '我拥抱成为的混乱、不完美而美丽的过程。',
    '每一天都带来新的事物去学习和发现。',
    '重新开始不是失败，而是智慧在行动。',
    '我正在成长为我一直梦想的那个版本的自己。',
    '我的进化正以恰好合适的速度展开。',
    '阅读、反思和练习塑造了我是谁。',
    '我正在以一年前无法想象的方式扩展。',
    '我最艰难的时刻给了我最大的成长。',
    '我随着每一年的过去，变得更加是我自己，而非更少。',
    '超越旧日版本的自己是我庆祝的事。',
    '我以初学者的心态和开放的心面对我的生活。',
    '我经历什么，就从中成长，始终如此。',
    '我的个人进化是我每日坚守的承诺。',
    '成为一个进行中的作品是我为之骄傲的事。',
    '我每一天都在自己身上发现新的力量。',
    '进步始终在发生，即使我看不见。',
    '最好的我还在前方，而我为此感到兴奋。',
    '新的开始让我充满兴奋，而非恐惧。',
    '每一次挫折都是为更伟大的事情做铺垫。',
    '我每天都在变得更智慧、更强大、更有韧性。',
    '还没想通一切，完全没关系。',
    '我深深地致力于自己成为过程的长远之路。',
    '成长很少是线性的，我对这个过程保持耐心。',
    '我以优雅和轻盈蜕去那些不再服务于我的。',
    '我的每一个版本都让我更接近现在这一个。',
    '我超越自己的极限，因为那是成长所在之处。',
    '我没有落后，我恰好在自己旅程的正确时间。',
    '我每天都在爱中、在智慧中、在喜悦中成长。',
    '细微的转变和悄然的蜕变值得被庆祝。',
    '我信任自己独特道路的展开。',
    '我正在进化，成为我一直注定要成为的一切。',
    '我在成长、我在发光，我正在变得完整。'
  ]),
  ('embrace_growth', 'zh-hant', 1400, '擁抱成長', array[
