    '新的開始讓我充滿興奮，而非恐懼。',
    '每一次挫折都是更偉大事物的鋪墊。',
    '我每天都變得更有智慧、更強大、更有韌性。',
    '沒有把一切都想清楚，完全沒問題。',
    '我深深地致力於自己成為的這場長期遊戲。',
    '成長很少是線性的，我對這個過程保有耐心。',
    '我帶著優雅與輕鬆，蛻去那些不再服務我的事物。',
    '我的每一個版本都讓我更接近現在的我。',
    '我超越自己的極限，因為那就是成長的地方。',
