    'Ich halte meine Beziehungen mit offenen Händen, nicht mit festen Fäusten.',
    'Ich pflege meine Verbindungen mit Zeit, Aufmerksamkeit und Fürsorge.',
    'Ich bin von Menschen umgeben, die mich feiern, so wie ich wirklich bin.',
    'Ich ziehe Liebe an, weil ich sie in meiner Lebensweise verkörpere.',
    'Ich lasse alte Wunden in meinen Beziehungen los und begrüße die Erneuerung.',
    'Verletzlich zu sein ist der Weg, wie ich es zulasse, wirklich gekannt zu werden.',
    'Ich investiere in die Beziehungen, die meine Seele erfüllen.',
    'Mein Herz ist offen für neue und tiefere Verbindungen.',
    'Ich bin präsent und aufmerksam in all meinen Beziehungen.',
    'Ich liebe großzügig ohne Angst vor Ablehnung oder Verlust.',
    'Ich ermuntere und ermutige die Menschen, die ich liebe, jeden Tag.',
    'Ich bin würdig von Freundschaften, die sich wie Nachhausekommen anfühlen.',
    'Ich umgebe mich mit Menschen, die mein Wachstum inspirieren.',
    'Ich lasse die Menschen, die ich liebe, sich wertgeschätzt und geliebt fühlen.',
    'Ich wähle Verbindung über Isolation, jeden einzelnen Mal.',
