    'Ich verdiene Beziehungen, die mich beflügeln, statt mich zu erschöpfen.',
    'Ich lasse Erwartungen los und lasse meine Beziehungen sich natürlich entfalten.',
    'Jede bedeutungsvolle Beziehung in meinem Leben ist ein Geschenk.',
    'Ich zeige Liebe durch meine Handlungen genauso wie durch meine Worte.',
    'Ich bin im Frieden mit den natürlichen Ebbe und Fluten der Verbindung.',
    'Meine Freundschaften sind auf Ehrlichkeit, Lachen und Vertrauen aufgebaut.',
    'Ich vertraue den Menschen, die ich in mein Herz gelassen habe.',
    'Ein guter Freund zu sein ist etwas, auf das ich stolz bin.',
