    'La vulnérabilité est la façon dont je me laisse vraiment connaître.',
    'J''investis dans les relations qui nourrissent mon âme.',
    'Mon cœur est ouvert à de nouvelles connexions et à des liens plus profonds.',
    'Je suis présent(e) et attentif(ve) dans toutes mes relations.',
    'J''aime généreusement sans craindre le rejet ni la perte.',
    'J''élève et encourage les personnes que j''aime chaque jour.',
