    'Mes amitiés sont fondées sur l''honnêteté, le rire et la confiance.',
    'Je fais confiance aux personnes que j''ai choisies de laisser entrer dans mon cœur.',
    'Être un(e) bon(ne) ami(e) est quelque chose dont je suis fier(ère).',
    'Je crée l''espace pour que les autres soient exactement qui ils sont.',
