    'Attiro amore perché lo incarno nel modo in cui vivo.',
    'Lascio andare le vecchie ferite nelle mie relazioni e accolgo il rinnovamento.',
    'La vulnerabilità è il modo in cui mi permetto di essere davvero conosciuto.',
    'Investo nelle relazioni che nutrono la mia anima.',
    'Il mio cuore è aperto a nuove connessioni e a quelle più profonde.',
    'Sono presente e attento in tutte le mie relazioni.',
    'Amo generosamente senza paura del rifiuto o della perdita.',
    'Elevo e incoraggio le persone che amo ogni giorno.',
    'Merito amicizie che sembrano un ritorno a casa.',
    'Mi circondo di persone che ispirano la mia crescita.',
    'Faccio sentire le persone che amo care e apprezzate.',
